def preprocess_dataset(raw_data, config):
    """
    Typical data preprocessing control flow.
    Shows how conditions and loops combine in real pipelines.
    """
    processed = []
    skipped = {"missing_text": 0, "missing_label": 0,
               "too_short": 0, "too_long": 0}

    for idx, record in enumerate(raw_data):

        # --- Validation Guards ---
        if "text" not in record or record["text"] is None:
            skipped["missing_text"] += 1
            continue

        if "label" not in record or record["label"] is None:
            skipped["missing_label"] += 1
            continue

        text = record["text"].strip()

        if len(text) < config["min_length"]:
            skipped["too_short"] += 1
            continue

        if len(text) > config["max_length"]:
            if config["truncate"]:
                text = text[:config["max_length"]]
            else:
                skipped["too_long"] += 1
                continue

        # --- Transformation ---
        if config["lowercase"]:
            text = text.lower()

        processed.append({
            "id": idx,
            "text": text,
            "label": int(record["label"]),
            "length": len(text)
        })

    # --- Summary Report ---
    total = len(raw_data)
    valid = len(processed)

    print(f"\nPreprocessing Complete:")
    print(f"  Total records:   {total}")
    print(f"  Valid records:   {valid} ({valid/total:.1%})")
    print(f"  Skipped:")
    for reason, count in skipped.items():
        if count > 0:
            print(f"    {reason}: {count}")

    return processed

