import time
import functools

def timer(func):
    """Measure execution time of any function"""
    @functools.wraps(func)   # Preserves the original function's metadata
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f"⏱ {func.__name__} took {elapsed:.4f}s")
        return result
    return wrapper


def retry(max_attempts=3, delay=1.0):
    """Retry a function on failure — useful for API calls to LLMs"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_attempts:
                        raise
                    print(f"Attempt {attempt} failed: {e}. Retrying in {delay}s...")
                    time.sleep(delay)
        return wrapper
    return decorator


def validate_inputs(func):
    """Validate that numeric inputs are in valid range"""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        for arg in args:
            if isinstance(arg, (int, float)):
                if not (-1e9 < arg < 1e9):
                    raise ValueError(f"Input {arg} is out of valid range")
        return func(*args, **kwargs)
    return wrapper


# Apply multiple decorators — they stack bottom to top
@timer
@validate_inputs
def train_step(learning_rate, batch_size, num_features):
    """Simulated training step"""
    time.sleep(0.1)   # Simulate work
    loss = learning_rate * num_features / batch_size
    return loss

