def log_to_file(filename="training.log"):
    """
    Decorator factory: returns a decorator.
    Three levels:
    1. Outer function receives decorator configuration
    2. Middle function receives the function to decorate
    3. Inner function is the actual wrapper
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            with open(filename, "a") as f:
                f.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} | "
                        f"{func.__name__} | result={result}\n")
            return result
        return wrapper
    return decorator


