def format_training_report(experiment_name, metrics, config):
    """
    Professional report formatting using various string techniques.
    """
    separator = "─" * 60

    # Header
    header = f"{'TRAINING REPORT':^60}"

    # Config section
    config_lines = [f"  {k:<20} {v}" for k, v in config.items()]
    config_section = "\n".join(config_lines)

    # Metrics table
    metric_header = f"  {'Metric':<20} {'Value':>10} {'Grade':>8}"
    metric_rows = []
    for name, value in metrics.items():
        grade = "A" if value > 0.90 else "B" if value > 0.80 else "C"
        metric_rows.append(f"  {name:<20} {value:>10.4f} {grade:>8}")
    metrics_section = "\n".join(metric_rows)

    report = f"""
{separator}
{header}
{separator}
Experiment: {experiment_name}
{separator}
CONFIGURATION:
{config_section}
{separator}
METRICS:
{metric_header}
{separator.replace('─', '-')}
{metrics_section}
{separator}
"""
    return report


