class Config:
    """Demonstrates attribute access control patterns"""

    DEFAULT_LR = 0.001    # Class-level constant (convention: UPPER_CASE)

    def __init__(self, **kwargs):
        self._config = {}      # Private by convention (single underscore)
        self.__secret = "key"  # Name-mangled (double underscore)
        self.update(**kwargs)

    def update(self, **kwargs):
        valid_keys = {"lr", "epochs", "batch_size", "dropout"}
        for key, value in kwargs.items():
            if key not in valid_keys:
                raise KeyError(f"Unknown config key: {key}")
            self._config[key] = value

    def get(self, key: str, default=None):
        return self._config.get(key, default)

    # __secret is name-mangled to _Config__secret
    def reveal(self):
        return self.__secret


