class LearningRateScheduler:
    """Demonstrates Python properties for controlled attribute access"""

    def __init__(self, initial_lr: float):
        self._lr = initial_lr      # Private backing attribute
        self._history = [initial_lr]

    @property
    def lr(self) -> float:
        """Getter — access with scheduler.lr"""
        return self._lr

    @lr.setter
    def lr(self, value: float) -> None:
        """Setter — validate before setting"""
        if not isinstance(value, (int, float)):
            raise TypeError(f"Learning rate must be numeric, got {type(value)}")
        if value <= 0:
            raise ValueError(f"Learning rate must be positive, got {value}")
        if value > 1.0:
            raise ValueError(f"Learning rate > 1.0 is unusual: {value}")

        print(f"  LR: {self._lr:.6f} → {value:.6f} "
              f"({'↓' if value < self._lr else '↑'} "
              f"{abs(1 - value/self._lr):.1%})")
        self._lr = value
        self._history.append(value)

    @lr.deleter
    def lr(self) -> None:
        """Deleter — called with del scheduler.lr"""
        raise AttributeError("Cannot delete learning rate")

    @property
    def history(self) -> list:
        """Read-only property"""
        return self._history.copy()   # Return copy to prevent mutation

    def step_decay(self, factor: float = 0.1,
                   drop: float = 0.5) -> None:
        """Decay learning rate by drop every factor-fraction of run"""
        self.lr = self._lr * drop


