# Method Resolution Order — C3 linearization algorithm
class A:
    def hello(self): print("A")

class B(A):
    def hello(self): print("B")

class C(A):
    def hello(self): print("C")

class D(B, C):
    pass

d = D()
d.hello()              # B — follows MRO
print(D.__mro__)       # D → B → C → A → object

# super() follows MRO — it calls the NEXT class in MRO, not the parent
class Base:
    def __init__(self):
        print("Base.__init__")

class Left(Base):
    def __init__(self):
        print("Left.__init__")
        super().__init__()

class Right(Base):
    def __init__(self):
        print("Right.__init__")
        super().__init__()

class Child(Left, Right):
    def __init__(self):
        print("Child.__init__")
        super().__init__()

child = Child()
# Output: Child → Left → Right → Base
# super() in Left calls Right, not Base!

import math
from typing import Iterator


class Vector:
    """
    A mathematical vector class.
    Demonstrates the most important magic methods.
    These same patterns are used in PyTorch Tensors,
    NumPy arrays, and Pandas DataFrames.
    """

    def __init__(self, *components: float):
        self.components = list(components)
        self.dim = len(components)

    # ── String representation ─────────────────────────────────────
    def __repr__(self) -> str:
        """Unambiguous string — used in debugging, repr()"""
        comp_str = ", ".join(f"{c:.3f}" for c in self.components)
        return f"Vector({comp_str})"

    def __str__(self) -> str:
        """Human-readable — used in print()"""
        return f"({', '.join(str(c) for c in self.components)})"

    # ── Arithmetic operators ──────────────────────────────────────
    def __add__(self, other: "Vector") -> "Vector":
        """self + other"""
        self._check_dims(other)
        return Vector(*(a + b for a, b in
                        zip(self.components, other.components)))

    def __sub__(self, other: "Vector") -> "Vector":
        """self - other"""
        self._check_dims(other)
        return Vector(*(a - b for a, b in
                        zip(self.components, other.components)))

    def __mul__(self, scalar: float) -> "Vector":
        """self * scalar (scalar multiplication)"""
        return Vector(*(c * scalar for c in self.components))

    def __rmul__(self, scalar: float) -> "Vector":
        """scalar * self (right multiplication)"""
        return self.__mul__(scalar)

    def __truediv__(self, scalar: float) -> "Vector":
        """self / scalar"""
        if scalar == 0:
            raise ZeroDivisionError("Cannot divide vector by zero")
        return Vector(*(c / scalar for c in self.components))

    def __matmul__(self, other: "Vector") -> float:
        """self @ other (dot product — @ operator)"""
        self._check_dims(other)
        return sum(a * b for a, b in
                   zip(self.components, other.components))

    def __neg__(self) -> "Vector":
        """-self"""
        return Vector(*(-c for c in self.components))

    def __abs__(self) -> float:
        """abs(self) — Euclidean magnitude"""
        return math.sqrt(sum(c**2 for c in self.components))

    # ── Comparison operators ──────────────────────────────────────
    def __eq__(self, other: object) -> bool:
        """self == other"""
        if not isinstance(other, Vector):
            return NotImplemented
        return self.components == other.components

    def __lt__(self, other: "Vector") -> bool:
        """self < other (by magnitude)"""
        return abs(self) < abs(other)

    def __len__(self) -> int:
        """len(self) — number of dimensions"""
        return self.dim

    # ── Container behavior ────────────────────────────────────────
    def __getitem__(self, index: int) -> float:
        """self[index]"""
        return self.components[index]

    def __setitem__(self, index: int, value: float) -> None:
        """self[index] = value"""
        self.components[index] = value

    def __iter__(self) -> Iterator[float]:
        """for c in self"""
        return iter(self.components)

    def __contains__(self, value: float) -> bool:
        """value in self"""
        return value in self.components

    # ── Boolean evaluation ────────────────────────────────────────
    def __bool__(self) -> bool:
        """bool(self) — False if zero vector"""
        return abs(self) > 0

    # ── Hashing (for use in sets/dicts) ──────────────────────────
    def __hash__(self) -> int:
        """hash(self) — makes Vector hashable"""
        return hash(tuple(self.components))

    # ── Internal helpers ──────────────────────────────────────────
    def _check_dims(self, other: "Vector") -> None:
        if self.dim != other.dim:
            raise ValueError(
                f"Dimension mismatch: {self.dim} vs {other.dim}"
            )

    # ── Vector operations ─────────────────────────────────────────
    def normalize(self) -> "Vector":
        """Return unit vector"""
        magnitude = abs(self)
        if magnitude == 0:
            raise ValueError("Cannot normalize zero vector")
        return self / magnitude

    def dot(self, other: "Vector") -> float:
        """Dot product (same as @ operator)"""
        return self @ other

    def cosine_similarity(self, other: "Vector") -> float:
        """Cosine similarity — fundamental in NLP/embeddings"""
        return self.dot(other) / (abs(self) * abs(other))


