class MetricStrategy(ABC):
    """Strategy: different metric implementations"""

    @abstractmethod
    def compute(self, y_true: list, y_pred: list) -> float:
        pass

    @abstractmethod
    def name(self) -> str:
        pass


class AccuracyMetric(MetricStrategy):
    def compute(self, y_true: list, y_pred: list) -> float:
        return sum(t == p for t, p in zip(y_true, y_pred)) / len(y_true)

    def name(self) -> str:
        return "accuracy"


class F1Metric(MetricStrategy):
    def compute(self, y_true: list, y_pred: list) -> float:
        tp = sum(t == 1 and p == 1 for t, p in zip(y_true, y_pred))
        fp = sum(t == 0 and p == 1 for t, p in zip(y_true, y_pred))
        fn = sum(t == 1 and p == 0 for t, p in zip(y_true, y_pred))
        precision = tp / (tp + fp) if (tp + fp) > 0 else 0
        recall = tp / (tp + fn) if (tp + fn) > 0 else 0
        return (2 * precision * recall / (precision + recall)
                if (precision + recall) > 0 else 0)

    def name(self) -> str:
        return "f1_score"


class ModelEvaluator:
    """Uses strategy pattern — metric can be swapped at runtime"""

    def __init__(self, metric: MetricStrategy):
        self._metric = metric

    @property
    def metric(self) -> MetricStrategy:
        return self._metric

    @metric.setter
    def metric(self, metric: MetricStrategy) -> None:
        self._metric = metric

    def evaluate(self, y_true: list, y_pred: list) -> dict:
        score = self._metric.compute(y_true, y_pred)
        return {self._metric.name(): score}


y_true = [1, 0, 1, 1, 0, 1, 0, 0]
y_pred = [1, 0, 1, 0, 0, 1, 1, 0]

evaluator = ModelEvaluator(metric=AccuracyMetric())
print(evaluator.evaluate(y_true, y_pred))

evaluator.metric = F1Metric()   # Swap strategy at runtime
print(evaluator.evaluate(y_true, y_pred))

