class MyClass(ParentClass):
    class_attr = "shared"      # Class attribute

    def __init__(self, value):
        super().__init__()     # Always call parent init
        self.value = value     # Instance attribute

    def method(self): ...      # Instance method (self)

    @classmethod
    def class_method(cls): ... # Class method (cls)

    @staticmethod
    def static_method(): ...   # Static method (no self/cls)

    @property
    def value(self): return self._value  # Getter

    @value.setter
