    def __getitem__(self, k):  # obj[k]
    def __add__(self, other):  # obj + other
    def __eq__(self, other):   # obj == other
    def __hash__(self): ...    # hash(obj) — needed for sets/dicts
    def __enter__(self): ...   # with statement entry
    def __exit__(self, *args): # with statement exit

