def robust_csv_reader(filepath: str,
                       delimiter: str = ",",
                       encoding: str = "utf-8",
                       skip_errors: bool = False):
    """
    Production-grade CSV reader that handles:
    - Different delimiters (comma, tab, semicolon)
    - Quoted fields with embedded delimiters
    - Encoding issues
    - Malformed rows
    - Missing values
    """
    import csv

    valid_rows = []
    error_rows = []

    try:
        with open(filepath, "r", newline="", encoding=encoding) as f:
            # Sniff delimiter if not specified
            sample = f.read(1024)
            f.seek(0)

            try:
                dialect = csv.Sniffer().sniff(sample)
                reader = csv.DictReader(f, dialect=dialect)
            except csv.Error:
                reader = csv.DictReader(f, delimiter=delimiter)

            for row_num, row in enumerate(reader, start=2):  # start=2 (header=1)
                try:
                    # Check for completely empty rows
                    if all(v is None or v == "" for v in row.values()):
                        continue

                    # Convert types where possible
                    cleaned = {}
                    for key, value in row.items():
                        if key is None:
                            continue
                        key = key.strip()
                        value = value.strip() if value else None

                        if value == "" or value is None:
                            cleaned[key] = None
                        else:
                            try:
                                cleaned[key] = int(value)
                            except (ValueError, TypeError):
                                try:
                                    cleaned[key] = float(value)
                                except (ValueError, TypeError):
                                    cleaned[key] = value

                    valid_rows.append(cleaned)

                except Exception as e:
                    if skip_errors:
                        error_rows.append({"row": row_num, "error": str(e)})
                    else:
                        raise

    except UnicodeDecodeError:
        # Try fallback encoding
        return robust_csv_reader(filepath, delimiter, "latin-1", skip_errors)

    print(f"Loaded {len(valid_rows)} valid rows, {len(error_rows)} errors")
    return valid_rows, error_rows


valid, errors = robust_csv_reader("dataset.csv", skip_errors=True)
for row in valid:
    print(row)

import json
import datetime
import math

class MLJSONEncoder(json.JSONEncoder):
    """
    Custom JSON encoder for ML-specific types.
    Handles: datetime, sets, numpy arrays, custom objects.
    """

    def default(self, obj):
        # datetime → ISO string
        if isinstance(obj, (datetime.datetime, datetime.date)):
            return obj.isoformat()

        # set → sorted list
        if isinstance(obj, set):
            return sorted(list(obj))

        # Handle numpy types (if numpy is available)
        try:
            import numpy as np
            if isinstance(obj, np.integer):
                return int(obj)
            if isinstance(obj, np.floating):
                return float(obj)
            if isinstance(obj, np.ndarray):
                return obj.tolist()
        except ImportError:
            pass

        # Handle NaN and Infinity
        if isinstance(obj, float):
            if math.isnan(obj):
                return "NaN"
            if math.isinf(obj):
                return "Infinity" if obj > 0 else "-Infinity"

        # Handle objects with to_dict method
        if hasattr(obj, 'to_dict'):
            return obj.to_dict()

        # Handle objects with __dict__
        if hasattr(obj, '__dict__'):
            return obj.__dict__

        return super().default(obj)


