from pathlib import Path
from typing import Any, Optional

class ConfigManager:
    """
    Production-grade configuration manager.
    Supports YAML configs with environment variable overrides.
    """

    def __init__(self, config_path: str):
        self._path = Path(config_path)
        self._config = {}
        self._load()

    def _load(self) -> None:
        """Load configuration from YAML file"""
        if not self._path.exists():
            raise FileNotFoundError(f"Config file not found: {self._path}")

        with open(self._path, "r", encoding="utf-8") as f:
            self._config = yaml.safe_load(f) or {}

        # Apply environment variable overrides
        self._apply_env_overrides()

    def _apply_env_overrides(self) -> None:
        """
        Override config values with environment variables.
        E.g., TRAINING_LEARNING_RATE=0.0001 overrides training.learning_rate
        """
        import os
        for key, value in os.environ.items():
            # Look for keys matching CONFIG_SECTION_KEY pattern
            parts = key.lower().split("_", 1)
            if len(parts) == 2 and parts[0] in self._config:
                section, param = parts
                if param in self._config.get(section, {}):
                    # Convert to appropriate type
                    original_value = self._config[section][param]
                    try:
                        if isinstance(original_value, bool):
                            self._config[section][param] = value.lower() == "true"
                        elif isinstance(original_value, int):
                            self._config[section][param] = int(value)
                        elif isinstance(original_value, float):
                            self._config[section][param] = float(value)
                        else:
                            self._config[section][param] = value
                    except ValueError:
                        pass

    def get(self, key_path: str, default: Any = None) -> Any:
        """
        Get config value using dot notation.
        E.g., config.get("training.learning_rate")
        """
        keys = key_path.split(".")
        value = self._config

        for key in keys:
            if isinstance(value, dict):
                value = value.get(key)
                if value is None:
                    return default
            else:
                return default

        return value

    def set(self, key_path: str, value: Any) -> None:
        """Set config value using dot notation"""
        keys = key_path.split(".")
        config = self._config

        for key in keys[:-1]:
            config = config.setdefault(key, {})

        config[keys[-1]] = value

    def save(self, filepath: Optional[str] = None) -> None:
        """Save current configuration to file"""
        save_path = Path(filepath) if filepath else self._path
        with open(save_path, "w", encoding="utf-8") as f:
            yaml.dump(self._config, f, default_flow_style=False)
        print(f"Config saved to {save_path}")

    def __getitem__(self, key: str) -> Any:
        return self._config[key]

    def __repr__(self) -> str:
        return f"ConfigManager(path='{self._path}')"


