def load_dataset(filepath: str) -> list:
    """
    Load a JSONL dataset with comprehensive error handling.
    Demonstrates all four exception handling clauses.
    """
    import json

    records = []
    file_handle = None

    try:
        file_handle = open(filepath, "r", encoding="utf-8")

        for line_num, line in enumerate(file_handle, start=1):
            line = line.strip()
            if not line:
                continue

            try:
                # Inner try for per-line errors
                record = json.loads(line)

                # Validate required fields
                if "text" not in record:
                    raise ValueError(
                        f"Missing 'text' field in record at line {line_num}"
                    )
                if "label" not in record:
                    raise ValueError(
                        f"Missing 'label' field in record at line {line_num}"
                    )

                records.append(record)

            except json.JSONDecodeError as e:
                print(f"Warning: Skipping malformed JSON at line {line_num}: {e}")
                continue
            except ValueError as e:
                print(f"Warning: Validation error at line {line_num}: {e}")
                continue

    except FileNotFoundError:
        raise FileNotFoundError(
            f"Dataset file not found: '{filepath}'\n"
            f"Make sure the file exists and the path is correct."
        )

    except PermissionError:
        raise PermissionError(
            f"Cannot read '{filepath}': permission denied.\n"
            f"Check file permissions."
        )

    except UnicodeDecodeError as e:
        raise ValueError(
            f"Encoding error in '{filepath}': {e}\n"
            f"Try specifying a different encoding (e.g., 'latin-1')"
        )

    else:
        # Only runs if no exception was raised
        print(f"✓ Successfully loaded {len(records)} records from '{filepath}'")

    finally:
        # Always close the file, even if an exception occurred
        if file_handle and not file_handle.closed:
            file_handle.close()

    return records

def parse_config_value(value: str, expected_type: type):
    """
    Demonstrates exception chaining with 'raise ... from ...'
    Creates a clear cause-and-effect chain in the traceback.
    """
    try:
        return expected_type(value)
    except (ValueError, TypeError) as e:
        # Chain exceptions to preserve original context
        raise ValueError(
            f"Cannot convert '{value}' to {expected_type.__name__}"
        ) from e   # 'from e' preserves the original exception


def load_config(config_dict: dict) -> dict:
    """Load and validate a configuration dictionary"""
    validated = {}

    type_map = {
        "learning_rate": float,
        "epochs": int,
        "batch_size": int,
        "dropout": float
    }

    for key, expected_type in type_map.items():
        if key in config_dict:
            try:
                validated[key] = parse_config_value(
                    config_dict[key], expected_type
                )
            except ValueError as e:
                # Add context about which config key failed
                raise ValueError(
                    f"Invalid configuration for '{key}': {e}"
                ) from e

    return validated


