def process_batch(batch: list, model) -> list:
    """
    Process a batch — re-raises after logging.
    """
    try:
        results = model.predict(batch)
        return results

    except MemoryError as e:
        # Log critical error, cannot recover — re-raise
        print(f"CRITICAL: Out of memory processing batch of {len(batch)}")
        raise   # Re-raises the same exception with full traceback

    except Exception as e:
        # Log unexpected error, add context, re-raise
        print(f"ERROR: Unexpected failure processing batch: {type(e).__name__}: {e}")
        raise RuntimeError(
            f"Batch processing failed for {len(batch)} samples"
        ) from e


def safe_process_batch(batch: list, model,
                       fallback_value=None) -> list:
    """
    Version that returns fallback on error instead of raising.
    Use when partial results are acceptable.
    """
    try:
        return process_batch(batch, model)
    except Exception as e:
        print(f"Warning: Batch failed, returning fallback: {e}")
        return [fallback_value] * len(batch)

