# Custom context manager for ML training errors
@contextmanager
def graceful_training_step(step_name: str, reraise: bool = True):
    """
    Context manager that adds context to training errors.
    """
    try:
        yield
    except MemoryError:
        print(f"OUT OF MEMORY during {step_name}")
        print("Try reducing batch size or model size")
        if reraise:
            raise
    except RuntimeError as e:
        if "CUDA" in str(e):
            print(f"CUDA ERROR during {step_name}: {e}")
            print("Try: torch.cuda.empty_cache()")
        if reraise:
            raise
    except Exception as e:
        print(f"UNEXPECTED ERROR during {step_name}: {type(e).__name__}: {e}")
        if reraise:
            raise


