# ── Exception Hierarchy for ML System ────────────────────────────────────────

class MLBaseException(Exception):
    """
    Base exception for all custom ML exceptions.
    All custom exceptions should inherit from this.
    Allows callers to catch all ML errors with one except clause.
    """
    def __init__(self, message: str, details: dict = None):
        super().__init__(message)
        self.message = message
        self.details = details or {}

    def __str__(self) -> str:
        if self.details:
            detail_str = ", ".join(f"{k}={v}" for k, v in self.details.items())
            return f"{self.message} [{detail_str}]"
        return self.message


# ── Data Exceptions ───────────────────────────────────────────────────────────

class DataException(MLBaseException):
    """Base class for data-related errors"""
    pass


class DataValidationError(DataException):
    """Raised when input data fails validation checks"""

    def __init__(self, field: str, issue: str,
                 value=None, expected=None):
        details = {"field": field, "issue": issue}
        if value is not None:
            details["value"] = repr(value)
        if expected is not None:
            details["expected"] = expected

        message = f"Data validation failed for field '{field}': {issue}"
        super().__init__(message, details)
        self.field = field
        self.issue = issue


class DataNotFoundError(DataException):
    """Raised when required data is missing"""

    def __init__(self, data_name: str, search_paths: list = None):
        message = f"Required data not found: '{data_name}'"
        details = {}
        if search_paths:
            details["searched"] = str(search_paths)
        super().__init__(message, details)


class DataShapeError(DataException):
    """Raised when data has unexpected shape"""

    def __init__(self, expected_shape: tuple,
                 actual_shape: tuple, context: str = ""):
        message = (f"Shape mismatch{' in ' + context if context else ''}: "
                  f"expected {expected_shape}, got {actual_shape}")
        super().__init__(message, {
            "expected": str(expected_shape),
            "actual": str(actual_shape)
        })


# ── Model Exceptions ──────────────────────────────────────────────────────────

class ModelException(MLBaseException):
    """Base class for model-related errors"""
    pass


class ModelNotFittedError(ModelException):
    """Raised when predict() is called before fit()"""

    def __init__(self, model_name: str):
        super().__init__(
            f"Model '{model_name}' is not fitted. "
            f"Call fit() before predict().",
            {"model": model_name}
        )


class ModelConvergenceError(ModelException):
    """Raised when model fails to converge"""

    def __init__(self, model_name: str, epochs_run: int,
                 final_loss: float, target_loss: float):
        super().__init__(
            f"Model '{model_name}' failed to converge after {epochs_run} epochs. "
            f"Final loss: {final_loss:.4f}, target: {target_loss:.4f}",
            {
                "model": model_name,
                "epochs": epochs_run,
                "final_loss": final_loss,
                "target_loss": target_loss
            }
        )


class ModelConfigError(ModelException):
    """Raised for invalid model configuration"""

    def __init__(self, param_name: str, issue: str,
                 value=None, valid_range=None):
        details = {"parameter": param_name}
        if value is not None:
            details["value"] = str(value)
        if valid_range:
            details["valid_range"] = str(valid_range)

        super().__init__(
            f"Invalid model configuration for '{param_name}': {issue}",
            details
        )


# ── Pipeline Exceptions ───────────────────────────────────────────────────────

class PipelineException(MLBaseException):
    """Base class for pipeline errors"""
    pass


class PipelineStepError(PipelineException):
    """Raised when a specific pipeline step fails"""

    def __init__(self, step_name: str, step_index: int,
                 original_error: Exception):
        super().__init__(
            f"Pipeline step '{step_name}' (index {step_index}) failed: "
            f"{type(original_error).__name__}: {original_error}",
            {"step": step_name, "index": step_index}
        )
        self.step_name = step_name
        self.original_error = original_error


# ── API Exceptions ────────────────────────────────────────────────────────────

class APIException(MLBaseException):
    """Base class for API-related errors"""
    pass


class RateLimitError(APIException):
    """Raised when API rate limit is exceeded"""

    def __init__(self, service: str, retry_after: int = None):
        details = {"service": service}
        if retry_after:
            details["retry_after_seconds"] = retry_after

        message = f"Rate limit exceeded for {service}"
        if retry_after:
            message += f". Retry after {retry_after} seconds."

        super().__init__(message, details)
        self.retry_after = retry_after


class TokenLimitError(APIException):
    """Raised when input exceeds model's token limit"""

    def __init__(self, model: str, token_count: int, token_limit: int):
        super().__init__(
            f"Input exceeds token limit for {model}: "
            f"{token_count} tokens > {token_limit} limit",
            {"model": model, "count": token_count, "limit": token_limit}
        )


# ── Using Custom Exceptions ───────────────────────────────────────────────────

def validate_training_data(X: list, y: list,
                            feature_names: list = None) -> None:
    """Validate training data with informative custom errors"""

    if not X:
        raise DataValidationError(
            field="X",
            issue="Training features cannot be empty",
            value=X
        )

    if not y:
        raise DataValidationError(
            field="y",
            issue="Training labels cannot be empty",
            value=y
        )

    if len(X) != len(y):
        raise DataShapeError(
            expected_shape=(len(X),),
            actual_shape=(len(y),),
            context="X and y must have same number of samples"
        )

    if len(X) < 10:
        raise DataValidationError(
            field="X",
            issue=f"Too few samples for reliable training",
            value=len(X),
            expected="at least 10 samples"
        )

    if feature_names and len(feature_names) != len(X[0]):
        raise DataValidationError(
            field="feature_names",
            issue="Number of feature names does not match number of features",
            value=len(feature_names),
            expected=len(X[0])
        )


