        print(f"  Type:   {type(data).__name__}")
        print(f"  Length: {len(data)}")

        if not data:
            print("  ⚠ EMPTY!")
            return

        print(f"\n  First {sample_size} records:")
        for i, record in enumerate(data[:sample_size]):
            print(f"    [{i}] {record}")

        if len(data) > sample_size:
            print(f"  ...")
            print(f"    [{len(data)-1}] {data[-1]}")

        # Check types
        types = set(type(r).__name__ for r in data)
        print(f"\n  Types found: {types}")

        # Check for None values
        none_count = sum(1 for r in data if r is None)
        if none_count:
            print(f"  ⚠ None values: {none_count}")

        # If records are dicts
        if data and isinstance(data[0], dict):
            all_keys = set()
            for record in data:
                all_keys.update(record.keys())
            print(f"\n  Keys: {sorted(all_keys)}")

            # Check for missing keys
            for key in sorted(all_keys):
                missing = sum(1 for r in data if key not in r or r[key] is None)
                if missing:
                    print(f"  ⚠ '{key}': {missing} missing values")

    @staticmethod
    def trace_function(func):
        """
        Decorator that traces function calls for debugging.
        Shows inputs, outputs, and exceptions.
        """
        import functools

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Format arguments for display
            args_repr = [repr(a)[:50] for a in args]
            kwargs_repr = [f"{k}={repr(v)[:30]}" for k, v in kwargs.items()]
            all_args = ", ".join(args_repr + kwargs_repr)

            print(f"\n→ Calling {func.__name__}({all_args})")

            try:
                result = func(*args, **kwargs)
                result_repr = repr(result)[:100]
                print(f"← {func.__name__} returned: {result_repr}")
                return result

            except Exception as e:
                print(f"✗ {func.__name__} raised {type(e).__name__}: {e}")
                raise

        return wrapper

    @staticmethod
    def check_invariants(data: list, invariants: dict) -> list:
        """
        Check data invariants — properties that should always hold.
        Returns list of violations found.

        invariants: dict of {description: check_function}
        """
        violations = []

        for i, record in enumerate(data):
            for description, check_fn in invariants.items():
                try:
                    if not check_fn(record):
                        violations.append({
                            "index": i,
                            "record": record,
                            "violation": description
                        })
                except Exception as e:
                    violations.append({
                        "index": i,
                        "record": record,
                        "violation": f"{description} (check error: {e})"
                    })

        if violations:
            print(f"⚠ Found {len(violations)} invariant violations:")
            for v in violations[:5]:
                print(f"  [{v['index']}] {v['violation']}")
        else:
            print(f"✓ All {len(invariants)} invariants satisfied")

        return violations


