from typing import Union, Optional, List, Any
import functools


def validate_input(func):
    """
    Decorator for automatic input validation using type hints.
    Industry pattern for preventing bugs at system boundaries.
    """
    import inspect

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        sig = inspect.signature(func)
        bound = sig.bind(*args, **kwargs)
        bound.apply_defaults()

        for param_name, value in bound.arguments.items():
            param = sig.parameters[param_name]
            if param.annotation != inspect.Parameter.empty:
                expected_type = param.annotation
                # Handle Optional[X] = Union[X, None]
                if hasattr(expected_type, '__origin__'):
                    continue   # Skip complex type hints for simplicity
                if not isinstance(value, expected_type):
                    raise TypeError(
                        f"Parameter '{param_name}' expected "
                        f"{expected_type.__name__}, "
                        f"got {type(value).__name__}"
                    )

        return func(*args, **kwargs)

    return wrapper


class RobustMLPipeline:
    """
    Demonstrates defensive programming throughout.
    Validates at every boundary, fails fast, fails clearly.
    """

    VALID_MODES = frozenset({"train", "eval", "inference"})

    def __init__(self, model_name: str,
                 mode: str = "inference",
                 max_retries: int = 3):

        # Validate at construction time — fail fast
        if not isinstance(model_name, str) or not model_name.strip():
            raise ValueError(
                f"model_name must be a non-empty string, "
                f"got: {repr(model_name)}"
            )

        if mode not in self.VALID_MODES:
            raise ValueError(
                f"mode must be one of {self.VALID_MODES}, "
                f"got: '{mode}'"
            )

        if not isinstance(max_retries, int) or max_retries < 0:
            raise ValueError(
                f"max_retries must be a non-negative integer, "
                f"got: {repr(max_retries)}"
            )

        self.model_name = model_name.strip()
        self.mode = mode
        self.max_retries = max_retries
        self._is_initialized = False

    def process(self, inputs: List[str]) -> List[dict]:
        """
        Process inputs with full defensive validation.
        """
        # Precondition checks
        if not self._is_initialized:
            raise RuntimeError(
                f"{type(self).__name__} must be initialized "
                f"before calling process(). Call initialize() first."
            )

        if not isinstance(inputs, list):
            raise TypeError(
                f"inputs must be a list, got {type(inputs).__name__}. "
                f"Wrap single strings: process([text])"
            )

        if not inputs:
            return []   # Empty input → empty output (not an error)

        # Validate each input
        for i, item in enumerate(inputs):
            if not isinstance(item, str):
                raise TypeError(
                    f"All inputs must be strings. "
                    f"Item at index {i} is {type(item).__name__}: {repr(item)}"
                )
            if len(item.strip()) == 0:
                raise ValueError(
                    f"Empty string at index {i}. "
                    f"All inputs must be non-empty."
                )

        # Process with retry logic
        results = []
        for i, text in enumerate(inputs):
            for attempt in range(1, self.max_retries + 1):
                try:
                    result = self._process_single(text)
                    results.append(result)
                    break
                except Exception as e:
                    if attempt == self.max_retries:
                        raise RuntimeError(
                            f"Failed to process input {i} after "
                            f"{self.max_retries} attempts: {e}"
                        ) from e
                    logger.warning(
                        f"Attempt {attempt}/{self.max_retries} failed "
                        f"for input {i}: {e}. Retrying..."
                    )

        # Postcondition check
        assert len(results) == len(inputs), (
            f"Internal error: output count {len(results)} != "
            f"input count {len(inputs)}"
        )

        return results

    def _process_single(self, text: str) -> dict:
        """Process a single text"""
        return {"text": text, "length": len(text), "model": self.model_name}

    def initialize(self) -> "RobustMLPipeline":
        """Initialize the pipeline"""
        print(f"Initializing pipeline: {self.model_name}")
        self._is_initialized = True
        return self

