# Building a custom iterator class
class EpochIterator:
    """
    Iterates over training data in epochs.
    Demonstrates the iterator protocol directly.
    """

    def __init__(self, data: list, num_epochs: int):
        self._data = data
        self._num_epochs = num_epochs
        self._current_epoch = 0
        self._current_idx = 0

    def __iter__(self):
        """Returns self — this object IS the iterator"""
        return self

    def __next__(self):
        """Returns next item or raises StopIteration"""
        if self._current_epoch >= self._num_epochs:
            raise StopIteration

        if self._current_idx >= len(self._data):
            self._current_epoch += 1
            self._current_idx = 0
            if self._current_epoch >= self._num_epochs:
                raise StopIteration

        item = self._data[self._current_idx]
        self._current_idx += 1
        return {
            "epoch": self._current_epoch + 1,
            "item": item,
            "step": self._current_epoch * len(self._data) + self._current_idx
        }

    def __len__(self):
        return len(self._data) * self._num_epochs


