def train(dataset: Dataset,
          processor: BatchProcessor) -> MetricsDict:
    """Clean, self-documenting signature using type aliases"""
    texts = [text for text, _ in dataset]
    labels = [label for _, label in dataset]
    predictions = processor(texts)
    accuracy = compute_accuracy(labels, predictions)
    return {"accuracy": accuracy, "samples": len(dataset)}

from typing import Protocol, runtime_checkable


@runtime_checkable
class Predictor(Protocol):
    """
    Structural subtyping — any class with these methods
    satisfies this protocol, without explicit inheritance.
    This is how frameworks like Scikit-learn work.
    """

    def fit(self, X: List, y: List) -> "Predictor":
        ...

    def predict(self, X: List) -> List:
        ...


class MyCustomModel:
    """Does NOT inherit from Predictor, but satisfies its interface"""

    def fit(self, X, y):
        return self

    def predict(self, X):
        return [0] * len(X)


model = MyCustomModel()
print(isinstance(model, Predictor))   # True — duck typing with Protocol

def evaluate(model: Predictor, X: List, y: List) -> float:
    """Accepts ANY object satisfying the Predictor protocol"""
    predictions = model.predict(X)
    return sum(p == t for p, t in zip(predictions, y)) / len(y)

