@dataclass
class TrainingState:
    """
    Mutable training state.
    field(default_factory=...) for mutable defaults.
    """
    epoch: int = 0
    global_step: int = 0
    best_metric: float = float('inf')
    best_epoch: int = 0

    train_losses: List[float] = field(default_factory=list)
    val_losses: List[float] = field(default_factory=list)
    val_metrics: Dict[str, List[float]] = field(default_factory=dict)

    # Field not included in __repr__ or comparisons
    _internal_cache: Dict = field(
        default_factory=dict,
        repr=False,
        compare=False
    )

    def update(self, train_loss: float,
               val_loss: float,
               val_accuracy: float) -> bool:
        """Update state and return True if this is a new best"""
        self.epoch += 1
        self.train_losses.append(train_loss)
        self.val_losses.append(val_loss)

        if "accuracy" not in self.val_metrics:
            self.val_metrics["accuracy"] = []
        self.val_metrics["accuracy"].append(val_accuracy)

        if val_loss < self.best_metric:
            self.best_metric = val_loss
            self.best_epoch = self.epoch
            return True
        return False

    @property
    def is_improving(self) -> bool:
        if len(self.val_losses) < 2:
            return True
        return self.val_losses[-1] < self.val_losses[-2]


