# Safe nested access patterns
def safe_get(data: dict, *keys, default=None):
    """Safely navigate nested dictionaries/lists"""
    current = data
    for key in keys:
        try:
            current = current[key]
        except (KeyError, IndexError, TypeError):
            return default
    return current


