# Handling APIs that return different shapes based on success/error
def parse_api_response(response: requests.Response) -> dict:
    """
    Robust response parsing that handles common API response patterns.
    """
    try:
        data = response.json()
    except json.JSONDecodeError:
        return {
            "success": False,
            "error": "Invalid JSON response",
            "raw_text": response.text[:500]
        }

    if response.status_code >= 400:
        # Many APIs nest error details differently
        error_message = (
            safe_get(data, "error", "message") or
            safe_get(data, "error") or
            safe_get(data, "message") or
            f"HTTP {response.status_code}"
        )
        return {
            "success": False,
            "error": error_message,
            "status_code": response.status_code
        }

    return {"success": True, "data": data}


