import requests
import time
import logging
from typing import Optional, Dict, Any, List
from dataclasses import dataclass, field


logger = logging.getLogger(__name__)


@dataclass
class APIClientConfig:
    base_url: str
    api_key: Optional[str] = None
    timeout: float = 30.0
    max_retries: int = 3
    rate_limit_calls: int = 60
    rate_limit_period: float = 60.0
    default_headers: Dict[str, str] = field(default_factory=dict)


class APIError(Exception):
    """Base exception for API client errors"""
    def __init__(self, message: str, status_code: int = None,
                 response_body: Any = None):
        super().__init__(message)
        self.status_code = status_code
        self.response_body = response_body


class RateLimitExceededError(APIError):
    """Raised when rate limit is hit and retries are exhausted"""
    pass


class AuthenticationError(APIError):
    """Raised for 401/403 responses"""
    pass


class BaseAPIClient:
    """
    Production-grade base class for API clients.
    Handles auth, retries, rate limiting, and error handling consistently.
    Subclass this for specific APIs (OpenAI, HuggingFace, custom services).
    """

    def __init__(self, config: APIClientConfig):
        self.config = config
        self.session = requests.Session()

        headers = {"Content-Type": "application/json"}
        if config.api_key:
            headers["Authorization"] = f"Bearer {config.api_key}"
        headers.update(config.default_headers)
        self.session.headers.update(headers)

        self._rate_limiter = RateLimiter(
            config.rate_limit_calls, config.rate_limit_period
        )

    def _request(self,
                 method: str,
                 endpoint: str,
                 params: Optional[Dict] = None,
                 json_data: Optional[Dict] = None,
                 retry_count: int = 0) -> Dict:
        """Core request method with full error handling"""

        url = f"{self.config.base_url.rstrip('/')}/{endpoint.lstrip('/')}"

        self._rate_limiter.acquire()

        try:
            logger.debug(f"{method} {url} | params={params}")

            response = self.session.request(
                method=method,
                url=url,
                params=params,
                json=json_data,
                timeout=self.config.timeout
            )

            return self._handle_response(response, method, endpoint,
                                          params, json_data, retry_count)

        except requests.exceptions.Timeout:
            if retry_count < self.config.max_retries:
                wait = 2 ** retry_count
                logger.warning(f"Timeout, retrying in {wait}s "
                              f"({retry_count+1}/{self.config.max_retries})")
                time.sleep(wait)
                return self._request(method, endpoint, params,
                                    json_data, retry_count + 1)
            raise APIError(f"Request timed out after {self.config.max_retries} retries")

        except requests.exceptions.ConnectionError as e:
            if retry_count < self.config.max_retries:
                wait = 2 ** retry_count
                logger.warning(f"Connection error, retrying in {wait}s")
                time.sleep(wait)
                return self._request(method, endpoint, params,
                                    json_data, retry_count + 1)
            raise APIError(f"Connection failed: {e}")

    def _handle_response(self, response: requests.Response,
                         method: str, endpoint: str,
                         params: Optional[Dict],
                         json_data: Optional[Dict],
                         retry_count: int) -> Dict:
        """Centralized response handling and error classification"""

        if response.status_code == 200 or response.status_code == 201:
            try:
                return response.json()
            except ValueError:
                return {"raw_content": response.text}

        if response.status_code == 429:
            if retry_count < self.config.max_retries:
                retry_after = float(response.headers.get("Retry-After", 2 ** retry_count))
                logger.warning(f"Rate limited (429). Waiting {retry_after}s...")
                time.sleep(retry_after)
                return self._request(method, endpoint, params,
                                    json_data, retry_count + 1)
            raise RateLimitExceededError(
                "Rate limit exceeded and max retries exhausted",
                status_code=429
            )

        if response.status_code in (401, 403):
            raise AuthenticationError(
                f"Authentication failed: {response.text[:200]}",
                status_code=response.status_code
            )

        if response.status_code >= 500:
            if retry_count < self.config.max_retries:
                wait = 2 ** retry_count
                logger.warning(f"Server error {response.status_code}, "
                              f"retrying in {wait}s")
                time.sleep(wait)
                return self._request(method, endpoint, params,
                                    json_data, retry_count + 1)
            raise APIError(
                f"Server error after retries: {response.status_code}",
                status_code=response.status_code,
                response_body=response.text[:500]
            )

        # Other 4xx errors — don't retry
        raise APIError(
            f"Request failed: {response.status_code} — {response.text[:300]}",
            status_code=response.status_code,
            response_body=self._safe_json(response)
        )

    @staticmethod
    def _safe_json(response: requests.Response) -> Any:
        try:
            return response.json()
        except ValueError:
            return response.text[:500]

    def get(self, endpoint: str, params: Optional[Dict] = None) -> Dict:
        return self._request("GET", endpoint, params=params)

    def post(self, endpoint: str, json_data: Optional[Dict] = None) -> Dict:
        return self._request("POST", endpoint, json_data=json_data)

    def put(self, endpoint: str, json_data: Optional[Dict] = None) -> Dict:
        return self._request("PUT", endpoint, json_data=json_data)

    def delete(self, endpoint: str) -> Dict:
        return self._request("DELETE", endpoint)

    def close(self) -> None:
        self.session.close()

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()

