class Vector:
    """Pure Python vector implementation for deep understanding"""

    def __init__(self, components: list):
        self.components = list(components)

    def __add__(self, other):
        return Vector([a + b for a, b in zip(self.components, other.components)])

    def __sub__(self, other):
        return Vector([a - b for a, b in zip(self.components, other.components)])

    def __mul__(self, scalar):
        return Vector([c * scalar for c in self.components])

    def dot(self, other) -> float:
        return sum(a * b for a, b in zip(self.components, other.components))

    def norm(self) -> float:
        return sum(c**2 for c in self.components) ** 0.5

    def normalize(self) -> "Vector":
        n = self.norm()
        return Vector([c / n for c in self.components])

    def cosine_similarity(self, other) -> float:
        return self.dot(other) / (self.norm() * other.norm())

    def __repr__(self):
        return f"Vector({self.components})"


class Matrix:
    """Pure Python matrix implementation for deep understanding"""

    def __init__(self, rows: list):
        self.rows = rows
        self.n_rows = len(rows)
        self.n_cols = len(rows[0]) if rows else 0

    def __add__(self, other) -> "Matrix":
        result = [[self.rows[i][j] + other.rows[i][j]
                  for j in range(self.n_cols)]
                 for i in range(self.n_rows)]
        return Matrix(result)

    def transpose(self) -> "Matrix":
        result = [[self.rows[i][j] for i in range(self.n_rows)]
                 for j in range(self.n_cols)]
        return Matrix(result)

    def multiply(self, other: "Matrix") -> "Matrix":
        """Standard matrix multiplication — O(n³) naive implementation"""
        if self.n_cols != other.n_rows:
            raise ValueError(
                f"Cannot multiply {self.n_rows}x{self.n_cols} "
                f"by {other.n_rows}x{other.n_cols}"
            )

        result = [[0.0] * other.n_cols for _ in range(self.n_rows)]

        for i in range(self.n_rows):
            for j in range(other.n_cols):
                for k in range(self.n_cols):
                    result[i][j] += self.rows[i][k] * other.rows[k][j]

        return Matrix(result)

    def determinant_2x2(self) -> float:
        """Determinant for a 2x2 matrix only"""
        if self.n_rows != 2 or self.n_cols != 2:
            raise ValueError("This method only supports 2x2 matrices")
        return self.rows[0][0]*self.rows[1][1] - self.rows[0][1]*self.rows[1][0]

    def __repr__(self):
        return "\n".join(str(row) for row in self.rows)


