-- % matches zero or more characters
-- _ matches exactly one character

-- Names starting with 'A'
SELECT name FROM customers WHERE name LIKE 'A%';

-- Names ending with 'ma'
SELECT name FROM customers WHERE name LIKE '%ma';

-- Names containing 'ar' anywhere
SELECT name FROM customers WHERE name LIKE '%ar%';

-- Names with exactly 10 characters
SELECT name FROM customers WHERE name LIKE '__________';

-- Email addresses from gmail
SELECT name, email FROM customers WHERE email LIKE '%@gmail%';
 -- NOT LIKE
SELECT name FROM customers WHERE name NOT LIKE 'A%';

-- All unique cities (removes duplicates)
SELECT DISTINCT city
FROM customers;

-- All unique city + plan_type combinations
SELECT DISTINCT city, plan_type
FROM customers
ORDER BY city, plan_type;

-- Count of distinct values (preview of aggregation)
SELECT COUNT(DISTINCT city) AS unique_cities
FROM customers;

-- WRONG — returns all columns, wastes network bandwidth, breaks if columns change
SELECT * FROM orders;

-- CORRECT — select only what you need
SELECT order_id, customer_id, amount, status FROM orders;

-- WRONG — alias doesn't exist at WHERE evaluation time
SELECT amount * 0.18 AS tax FROM orders WHERE tax > 200;

-- CORRECT — repeat the expression
SELECT amount * 0.18 AS tax FROM orders WHERE amount * 0.18 > 200;
-- Or use a subquery (covered in Chapter 24)

-- COUNT — number of rows
SELECT COUNT(*) AS total_customers FROM customers;
-- COUNT(*) counts all rows including NULLs

SELECT COUNT(age) AS customers_with_age FROM customers;
-- COUNT(col) counts only non-NULL values in that column

SELECT COUNT(DISTINCT city) AS unique_cities FROM customers;
-- COUNT(DISTINCT col) counts unique non-NULL values
 -- SUM — total of numeric values
SELECT SUM(amount) AS total_revenue FROM orders;

-- SUM with condition (conditional aggregation)
SELECT
    SUM(CASE WHEN status = 'completed' THEN amount ELSE 0 END) AS completed_revenue,
    SUM(CASE WHEN status = 'pending'   THEN amount ELSE 0 END) AS pending_revenue,
    SUM(CASE WHEN status = 'cancelled' THEN amount ELSE 0 END) AS cancelled_revenue
FROM orders;
 -- AVG — arithmetic mean (ignores NULLs)
SELECT AVG(amount) AS avg_order_value FROM orders;

SELECT AVG(age) AS avg_age FROM customers;
-- NULLs in age are ignored — AVG is over non-NULL rows only
 -- MIN and MAX
SELECT
    MIN(amount) AS smallest_order,
    MAX(amount) AS largest_order,
    MAX(amount) - MIN(amount) AS order_range
FROM orders;

SELECT
    MIN(signup_date) AS earliest_signup,
    MAX(signup_date) AS latest_signup
FROM customers;

-- WRONG — returns 0 rows if subquery contains any NULLs
SELECT * FROM customers
WHERE customer_id NOT IN (
    SELECT customer_id FROM orders  -- If any customer_id is NULL here → disaster
);

-- CORRECT — filter NULLs out of the subquery
SELECT * FROM customers
WHERE customer_id NOT IN (
    SELECT customer_id FROM orders WHERE customer_id IS NOT NULL
);

-- SAFEST — use NOT EXISTS instead
SELECT * FROM customers AS c
WHERE NOT EXISTS (
    SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id
);

-- CTE: best for readability, reusable within the same query
WITH cte AS (SELECT ...)
SELECT * FROM cte JOIN cte as cte2 ON ...;  -- Can reference the same CTE multiple times

-- Subquery: inline, less readable, cannot be reused
SELECT * FROM (SELECT ...) AS sub;

-- Temp table: persists for the session, good for very large intermediate results
CREATE TEMP TABLE temp_result AS SELECT ...;
SELECT * FROM temp_result;
DROP TABLE temp_result;

-- See the query plan
EXPLAIN SELECT * FROM model_results WHERE accuracy > 0.90;

-- See actual execution times
EXPLAIN ANALYZE SELECT * FROM model_results WHERE accuracy > 0.90;

-- Create indexes for columns you frequently filter, join, or order by
CREATE INDEX idx_model_results_accuracy ON model_results(accuracy);
CREATE INDEX idx_model_results_date ON model_results(run_date);

-- Composite index for queries that filter on multiple columns together
CREATE INDEX idx_model_results_name_date
    ON model_results(model_name, run_date DESC);

-- Partial index — only indexes rows matching a condition
-- Useful when most queries filter to a subset
CREATE INDEX idx_recent_models
    ON model_results(model_name, accuracy)
    WHERE run_date >= '2026-01-01';

-- Index on JSON field
CREATE INDEX idx_hyperparams_optimizer
    ON model_experiments USING GIN (hyperparams);

-- Index on text search
CREATE INDEX idx_model_name_text
    ON model_results USING GIN (to_tsvector('english', model_name));

-- SLOW: function on indexed column prevents index use
SELECT * FROM model_results WHERE LOWER(model_name) = 'bert';

-- FAST: function index, or store data normalized
CREATE INDEX idx_model_name_lower ON model_results(LOWER(model_name));
SELECT * FROM model_results WHERE LOWER(model_name) = 'bert';

-- SLOW: SELECT * retrieves all columns, even unused ones
SELECT * FROM large_model_table WHERE run_date > '2026-01-01';

-- FAST: only request what you need
SELECT model_name, accuracy, run_date
FROM large_model_table
WHERE run_date > '2026-01-01';

-- SLOW: correlated subquery runs once per row
SELECT model_name, accuracy
FROM model_results mr
WHERE accuracy > (
    SELECT AVG(accuracy) FROM model_results   -- Runs for every row!
    WHERE dataset = mr.dataset
);

-- FAST: use a window function or CTE instead
WITH dataset_avgs AS (
    SELECT dataset, AVG(accuracy) AS avg_acc
    FROM model_results
    GROUP BY dataset
)
SELECT mr.model_name, mr.accuracy
FROM model_results mr
JOIN dataset_avgs da ON mr.dataset = da.dataset
WHERE mr.accuracy > da.avg_acc;

-- WRONG: crashes on weeks with zero trials
SELECT SUM(paid) / SUM(trials) AS conversion_rate FROM funnel;

-- CORRECT: returns NULL instead of error
SELECT SUM(paid) / NULLIF(SUM(trials), 0) AS conversion_rate FROM funnel;

