from collections import deque

class Queue:
    """
    Queue implementation using collections.deque.
    FIFO — First In, First Out.
    All operations are O(1).

    deque (double-ended queue) supports O(1) appends and pops
    from both ends, making it the correct underlying structure for queues.
    """

    def __init__(self):
        self._data = deque()

    def enqueue(self, item):
        """Add item to the rear of the queue — O(1)."""
        self._data.append(item)

    def dequeue(self):
        """
        Remove and return the front item — O(1).
        Raises IndexError if queue is empty.
        """
        if self.is_empty():
            raise IndexError("dequeue from empty queue")
        return self._data.popleft()

    def front(self):
        """Return the front item without removing it — O(1)."""
        if self.is_empty():
            raise IndexError("front of empty queue")
        return self._data[0]

    def rear(self):
        """Return the rear item without removing it — O(1)."""
        if self.is_empty():
            raise IndexError("rear of empty queue")
        return self._data[-1]

    def is_empty(self) -> bool:
        return len(self._data) == 0

    def size(self) -> int:
        return len(self._data)

    def __len__(self):
        return self.size()

    def __repr__(self):
        return f"Queue(front → {list(self._data)} ← rear)"


