class LinkedQueue:
    """
    Queue implemented using a linked list.
    Maintains a head pointer (front) and tail pointer (rear)
    for O(1) enqueue and dequeue.
    """

    class _Node:
        __slots__ = ["value", "next"]
        def __init__(self, value):
            self.value = value
            self.next = None

    def __init__(self):
        self._head = None   # Front (dequeue from here)
        self._tail = None   # Rear  (enqueue here)
        self._size = 0

    def enqueue(self, item):
        """Add to tail — O(1)."""
        new_node = self._Node(item)
        if self._tail is None:
            # Empty queue — head and tail both point to new node
            self._head = self._tail = new_node
        else:
            self._tail.next = new_node
            self._tail = new_node
        self._size += 1

    def dequeue(self):
        """Remove from head — O(1)."""
        if self.is_empty():
            raise IndexError("dequeue from empty queue")
        value = self._head.value
        self._head = self._head.next
        if self._head is None:
            self._tail = None   # Queue is now empty
        self._size -= 1
        return value

    def front(self):
        if self.is_empty():
            raise IndexError("empty queue")
        return self._head.value

    def is_empty(self) -> bool:
        return self._head is None

    def size(self) -> int:
        return self._size

