class QueueUsingTwoStacks:
    def __init__(self):
        self.inbox = []
        self.outbox = []

    def enqueue(self, val):
        self.inbox.append(val)

    def dequeue(self):
        if not self.outbox:
            while self.inbox:
                self.outbox.append(self.inbox.pop())
        if not self.outbox:
            raise IndexError("dequeue from empty queue")
        return self.outbox.pop()

