class GraphMatrix:
    """
    Adjacency matrix representation.

    matrix[i][j] = weight of edge from i to j (0 if no edge)

    Space: O(V²) — stores all possible edges

    Best for: dense graphs, O(1) edge existence check,
              Floyd-Warshall algorithm
    """

    def __init__(self, n: int, directed: bool = False):
        self.n        = n
        self.directed = directed
        self.matrix   = [[0] * n for _ in range(n)]

    def add_edge(self, u: int, v: int, weight: float = 1):
        self.matrix[u][v] = weight
        if not self.directed:
            self.matrix[v][u] = weight

    def has_edge(self, u: int, v: int) -> bool:
        return self.matrix[u][v] != 0     # O(1)

    def get_neighbors(self, u: int) -> list:
        return [(v, self.matrix[u][v])
                for v in range(self.n)
                if self.matrix[u][v] != 0]

    def print_matrix(self):
        print("\nAdjacency Matrix:")
        print("  ", "  ".join(str(i) for i in range(self.n)))
        for i, row in enumerate(self.matrix):
            print(f"{i} ", "  ".join(str(v) for v in row))


