def mse_criterion(y):
    """MSE impurity for regression trees — variance of target values"""
    if len(y) == 0:
        return 0.0
    return np.var(y)


def mse_gain(y_parent, y_left, y_right):
    """Variance reduction from a split"""
    n       = len(y_parent)
    n_left  = len(y_left)
    n_right = len(y_right)

    parent_mse = mse_criterion(y_parent)
    weighted_child_mse = (
        (n_left  / n) * mse_criterion(y_left) +
        (n_right / n) * mse_criterion(y_right)
    )
    return parent_mse - weighted_child_mse


# Regression tree prediction: predict the MEAN of training samples in each leaf
class RegressionTreeScratch:
    """
    Decision Tree Regressor — predicts mean of leaf samples.
    Uses variance reduction (MSE gain) as splitting criterion.
    """

    def __init__(self, max_depth=5, min_samples_split=5, min_samples_leaf=2):
        self.max_depth         = max_depth
        self.min_samples_split = min_samples_split
        self.min_samples_leaf  = min_samples_leaf
        self.root              = None

    def fit(self, X, y):
        self.root = self._build_tree(X, y, depth=0)
        return self

    def _build_tree(self, X, y, depth):
        n_samples = len(y)
        variance  = mse_criterion(y)
        node_value = np.mean(y)   # Leaf prediction = mean of samples

        should_stop = (
            (self.max_depth is not None and depth >= self.max_depth) or
            (n_samples < self.min_samples_split) or
            (variance < 1e-7)
        )

        if should_stop:
            return {"leaf": True, "value": node_value, "n_samples": n_samples}

        # Find best split using MSE gain
        best_gain      = -np.inf
        best_feature   = None
        best_threshold = None

        for feature_idx in range(X.shape[1]):
            values     = X[:, feature_idx]
            thresholds = (np.sort(np.unique(values))[:-1] +
                         np.sort(np.unique(values))[1:]) / 2

            for threshold in thresholds:
                left_mask  = values <= threshold
                right_mask = ~left_mask

                if (left_mask.sum() < self.min_samples_leaf or
                        right_mask.sum() < self.min_samples_leaf):
                    continue

                gain = mse_gain(y, y[left_mask], y[right_mask])

                if gain > best_gain:
                    best_gain      = gain
                    best_feature   = feature_idx
                    best_threshold = threshold

        if best_feature is None:
            return {"leaf": True, "value": node_value, "n_samples": n_samples}

        left_mask  = X[:, best_feature] <= best_threshold
        right_mask = ~left_mask

        return {
            "leaf":      False,
            "feature":   best_feature,
            "threshold": best_threshold,
            "value":     node_value,
            "n_samples": n_samples,
            "left":      self._build_tree(X[left_mask],  y[left_mask],  depth + 1),
            "right":     self._build_tree(X[right_mask], y[right_mask], depth + 1),
        }

    def _predict_single(self, x, node):
        if node["leaf"]:
            return node["value"]
        if x[node["feature"]] <= node["threshold"]:
            return self._predict_single(x, node["left"])
        else:
            return self._predict_single(x, node["right"])

    def predict(self, X):
        return np.array([self._predict_single(x, self.root) for x in X])

    def score(self, X, y):
        y_pred = self.predict(X)
        return r2_score(y, y_pred)


