def initialize_network(model: nn.Module,
                        activation: str = "relu") -> nn.Module:
    """
    Apply correct initialization to every layer in a network.
    This function should be called on every new model before training.

    Rules:
    - Linear layers → He (ReLU) or Xavier (tanh/sigmoid)
    - Biases → always zero
    - Embedding layers → Normal(0, 0.01) or scale by 1/√vocab_size
    - LayerNorm/BatchNorm → weight=1, bias=0 (identity at init)
    - LSTM/GRU → Orthogonal for recurrent weights, Xavier for input weights
    """
    for name, module in model.named_modules():

        if isinstance(module, nn.Linear):
            if activation in ("relu", "leaky_relu", "elu"):
                nn.init.kaiming_normal_(
                    module.weight,
                    mode="fan_in",
                    nonlinearity="relu"
                )
            elif activation in ("tanh", "sigmoid"):
                nn.init.xavier_normal_(module.weight)
            elif activation == "selu":
                # LeCun normal: σ = √(1/n_in)
                nn.init.normal_(module.weight,
                                 std=math.sqrt(1.0 / module.weight.shape[1]))
            else:
                nn.init.xavier_normal_(module.weight)

            if module.bias is not None:
                nn.init.zeros_(module.bias)

        elif isinstance(module, (nn.BatchNorm1d, nn.BatchNorm2d,
                                  nn.LayerNorm)):
            # Normalization layers: initialize to identity
            if hasattr(module, "weight") and module.weight is not None:
                nn.init.ones_(module.weight)   # Scale = 1
            if hasattr(module, "bias") and module.bias is not None:
                nn.init.zeros_(module.bias)    # Shift = 0

        elif isinstance(module, nn.Embedding):
            nn.init.normal_(module.weight, mean=0.0, std=0.01)

        elif isinstance(module, (nn.LSTM, nn.GRU)):
            for param_name, param in module.named_parameters():
                if "weight_ih" in param_name:
                    nn.init.xavier_uniform_(param)
                elif "weight_hh" in param_name:
                    nn.init.orthogonal_(param)
                elif "bias" in param_name:
                    nn.init.zeros_(param)

    print(f"Initialized model with {activation} initialization strategy")
    return model


# ─── Example: build and initialize a deep network ──────────────

class DeepNetwork(nn.Module):
    def __init__(self, input_dim: int, hidden_dim: int,
                  output_dim: int, n_layers: int = 8):
        super().__init__()
        layers = [nn.Linear(input_dim, hidden_dim), nn.ReLU()]
        for _ in range(n_layers - 2):
            layers += [nn.Linear(hidden_dim, hidden_dim), nn.ReLU()]
        layers += [nn.Linear(hidden_dim, output_dim)]
        self.network = nn.Sequential(*layers)

    def forward(self, x):
        return self.network(x)

model = DeepNetwork(128, 256, 10, n_layers=8)
model = initialize_network(model, activation="relu")

