from fastapi import FastAPI, UploadFile
import spacy
import pdfplumber
from collections import defaultdict

app = FastAPI(title="Document Entity Extraction API")
nlp = spacy.load("en_core_web_trf")

def extract_text_from_pdf(file) -> str:
    text = ""
    with pdfplumber.open(file) as pdf:
        for page in pdf.pages:
            page_text = page.extract_text()
            if page_text:
                text += page_text + "\n"
    return text

def extract_entities(text: str) -> dict:
    doc = nlp(text)
    entities = defaultdict(set)

    for ent in doc.ents:
        entities[ent.label_].add(ent.text.strip())

    return {label: sorted(list(values)) for label, values in entities.items()}

@app.post("/extract-entities")
async def extract_entities_endpoint(file: UploadFile):
    if file.filename.endswith(".pdf"):
        text = extract_text_from_pdf(file.file)
    else:
        text = (await file.read()).decode("utf-8")

    entities = extract_entities(text)

    return {
        "filename": file.filename,
        "entity_count": sum(len(v) for v in entities.values()),
        "entities": entities
    }

