# Conceptual illustration of running a HumanEval-style check
def check_generated_code(generated_function_code: str, test_cases: list) -> float:
    """
    HumanEval-style evaluation: execute generated code against test cases
    and measure pass rate. Real implementations run this in a sandboxed environment.
    """
    namespace = {}
    exec(generated_function_code, namespace)

    passed = 0
    for test_input, expected_output in test_cases:
        try:
            result = namespace["solution"](*test_input)
            if result == expected_output:
                passed += 1
        except Exception:
            pass

    return passed / len(test_cases)

from collections import Counter

def self_consistency_answer(question, llm_call, num_samples=5, temperature=0.7):
    """
    Generates multiple CoT reasoning chains and returns the most common
    final answer — meaningfully improves accuracy on reasoning-heavy tasks
    at the cost of num_samples times the compute/latency/cost.
    """
    cot_prompt = f"{question}\n\nLet's think step by step."

    answers = []
    for _ in range(num_samples):
        response = llm_call(cot_prompt, temperature=temperature)
        final_answer = extract_final_answer(response)
        answers.append(final_answer)

    answer_counts = Counter(answers)
    most_common_answer, count = answer_counts.most_common(1)[0]

    return {
        "answer": most_common_answer,
        "confidence": count / num_samples,
        "all_answers": answers
    }

def extract_final_answer(response_text):
    """
    Simplified extraction — in production, use a structured output
    prompt or regex to reliably pull the final answer from the reasoning text.
    """
    lines = response_text.strip().split("\n")
    for line in reversed(lines):
        if "answer" in line.lower() or "the answer is" in line.lower():
            return line.strip()
    return lines[-1].strip()

