# prompt_library.py
# A reusable prompt template system with versioning, validation,
# and a simple test harness — the kind of internal tool most GenAI
# teams build early in a project's life

import json
import re
from dataclasses import dataclass, field
from typing import Callable, Optional
from datetime import datetime

@dataclass
class PromptTemplate:
    name: str
    version: str
    template: str
    required_variables: list = field(default_factory=list)
    output_parser: Optional[Callable] = None
    created_at: str = field(default_factory=lambda: datetime.now().isoformat())

    def render(self, **kwargs) -> str:
        missing = [v for v in self.required_variables if v not in kwargs]
        if missing:
            raise ValueError(f"[{self.name} v{self.version}] Missing variables: {missing}")
        return self.template.format(**kwargs)

    def parse_output(self, raw_output: str):
        if self.output_parser:
            return self.output_parser(raw_output)
        return raw_output


class PromptLibrary:
    """Stores and manages multiple versions of prompt templates"""

    def __init__(self):
        self.templates = {}  # {name: {version: PromptTemplate}}

    def register(self, template: PromptTemplate):
        if template.name not in self.templates:
            self.templates[template.name] = {}
        self.templates[template.name][template.version] = template
        print(f"Registered '{template.name}' v{template.version}")

    def get(self, name: str, version: str = "latest") -> PromptTemplate:
        versions = self.templates.get(name)
        if not versions:
            raise KeyError(f"No template named '{name}' found")

        if version == "latest":
            latest_version = sorted(versions.keys())[-1]
            return versions[latest_version]

        if version not in versions:
            raise KeyError(f"Version '{version}' not found for template '{name}'")
        return versions[version]

    def list_versions(self, name: str):
        return list(self.templates.get(name, {}).keys())


def parse_json_output(raw_output: str):
    """Common output parser: extract and validate JSON"""
    cleaned = raw_output.strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(json)?|```$", "", cleaned).strip()
    return json.loads(cleaned)


class PromptTestCase:
    """A single test case for validating a prompt template's behavior"""

    def __init__(self, inputs: dict, validation_fn: Callable, description: str):
        self.inputs = inputs
        self.validation_fn = validation_fn
        self.description = description


def run_prompt_tests(template: PromptTemplate, test_cases: list, mock_llm_call: Callable):
    """
    Runs a suite of test cases against a prompt template using a
    (mock or real) LLM call function. Returns a pass/fail report.
    """
    results = []

    for i, test in enumerate(test_cases, 1):
        rendered_prompt = template.render(**test.inputs)
        raw_output = mock_llm_call(rendered_prompt)

        try:
            parsed = template.parse_output(raw_output)
            passed = test.validation_fn(parsed)
            error = None
        except Exception as e:
            passed = False
            parsed = None
            error = str(e)

        results.append({
            "test_num": i,
            "description": test.description,
            "passed": passed,
            "error": error,
            "output": parsed
        })

    return results


def print_test_report(results, template_name):
    passed_count = sum(1 for r in results if r["passed"])
    total = len(results)

    print(f"\n{'='*60}")
    print(f"  TEST REPORT: {template_name}")
    print(f"{'='*60}")
    print(f"Passed: {passed_count}/{total}\n")

    for r in results:
        status = "✓ PASS" if r["passed"] else "✗ FAIL"
        print(f"[{status}] Test {r['test_num']}: {r['description']}")
        if not r["passed"]:
            print(f"          Error: {r['error']}")
            print(f"          Output: {r['output']}")


