def route_by_complexity(query, complexity_score):
    """Route simple queries to cheap models, complex ones to premium models"""
    if complexity_score < 0.3:
        return "gpt-4o-mini"      # cheap, fast, good enough for simple tasks
    elif complexity_score < 0.7:
