def dot_product(a, b):
    return np.dot(np.array(a), np.array(b))

# If embeddings are already normalized to unit length,
# dot product and cosine similarity produce identical rankings
# but dot product is computationally cheaper (no division/norm step)

def euclidean_distance(a, b):
    return np.linalg.norm(np.array(a) - np.array(b))

# Lower = more similar (this is a distance, not a similarity)
# Sensitive to vector magnitude, unlike cosine similarity

def hybrid_search(query: str, vectorstore, bm25, chunks, alpha=0.5, k=5):
    """
    Combines dense (semantic) and sparse (BM25) scores.
    alpha=1.0 → pure semantic, alpha=0.0 → pure keyword
    """
    # Dense scores
    dense_results = vectorstore.similarity_search_with_score(query, k=len(chunks))
    dense_scores = {doc.page_content: 1 - score for doc, score in dense_results}

    # Sparse scores
    bm25_scores_raw = bm25.get_scores(query.split())
    max_bm25 = max(bm25_scores_raw) if max(bm25_scores_raw) > 0 else 1
    sparse_scores = {
        chunks[i].page_content: bm25_scores_raw[i] / max_bm25
        for i in range(len(chunks))
    }

    # Combine with weighted sum
    combined_scores = {}
    for text in dense_scores:
        d_score = dense_scores.get(text, 0)
        s_score = sparse_scores.get(text, 0)
        combined_scores[text] = alpha * d_score + (1 - alpha) * s_score

    ranked = sorted(combined_scores.items(), key=lambda x: x[1], reverse=True)
    return ranked[:k]

def reciprocal_rank_fusion(dense_ranked_ids, sparse_ranked_ids, k=60):
    """
    RRF: score = sum(1 / (k + rank)) across all ranking lists.
    Avoids needing to normalize incompatible score scales.
    """
    scores = {}
    for rank, doc_id in enumerate(dense_ranked_ids):
        scores[doc_id] = scores.get(doc_id, 0) + 1 / (k + rank + 1)
    for rank, doc_id in enumerate(sparse_ranked_ids):
        scores[doc_id] = scores.get(doc_id, 0) + 1 / (k + rank + 1)

    return sorted(scores.items(), key=lambda x: x[1], reverse=True)

def generate_with_fallback(query: str, retrieved_chunks: list, min_relevance_score=0.5):
    """Detect when retrieval didn't find relevant enough context"""

    relevant_chunks = [c for c in retrieved_chunks if c["score"] >= min_relevance_score]

    if not relevant_chunks:
        return {
            "answer": "I don't have enough information in my knowledge base to answer this question accurately.",
            "sources": [],
            "confidence": "low"
        }

    prompt = build_rag_prompt(query, relevant_chunks)
    # ... call LLM ...
    return {"answer": "...", "sources": relevant_chunks, "confidence": "high"}

