    @staticmethod
    def text_splitter_comparison(documents: list) -> dict:
        """
        Text splitting is one of the most impactful decisions in RAG.
        Chunk size and overlap determine what context is available at retrieval time.

        The fundamental tradeoff:
        - Large chunks: more context per chunk, fewer chunks, lower recall
        - Small chunks: less context, more chunks, higher recall but fragmented

        Overlap prevents losing information at chunk boundaries.
        """
        splitters = {
            "RecursiveCharacterTextSplitter": {
                "splitter": RecursiveCharacterTextSplitter(
                    chunk_size=200,
                    chunk_overlap=40,
                    separators=["\n\n", "\n", ". ", "! ", "? ", ", ", " ", ""]
                ),
                "description": (
                    "RECOMMENDED: Tries to split on paragraphs first, "
                    "then sentences, then words, then characters. "
                    "Preserves semantic coherence as much as possible."
                )
            },
            "CharacterTextSplitter": {
                "splitter": CharacterTextSplitter(
                    chunk_size=200,
                    chunk_overlap=40,
                    separator="\n"
                ),
                "description": (
                    "Splits on a fixed separator. Simple but may cut "
                    "mid-sentence if separator is not found."
                )
            },
            "TokenTextSplitter": {
                "splitter": TokenTextSplitter(
                    chunk_size=100,
                    chunk_overlap=20
                ),
                "description": (
                    "Splits on token count (not character count). "
                    "Use when you need precise token budget control "
                    "for LLM context windows."
                )
            }
        }

        results = {}
        print("Text Splitter Comparison:")
        print("=" * 65)

        for name, info in splitters.items():
            try:
                chunks = info["splitter"].split_documents(documents)
                results[name] = chunks

                sizes = [len(c.page_content) for c in chunks]
                print(f"\n  {name}:")
                print(f"    Description:    {info['description'][:70]}...")
