def simple_llm_call(question, llm):
    """No agency — one prompt, one response"""
    return llm.generate(question)

def naive_rag(question, retriever, llm):
    """Fixed pipeline — always retrieves, regardless of whether it's needed"""
    context = retriever.search(question)
    return llm.generate(f"Context: {context}\nQuestion: {question}")

def simple_agent(question, tools, llm, max_steps=5):
    """Agentic — LLM decides whether/which tool to use, and when to stop"""
    history = [f"Question: {question}"]

    for step in range(max_steps):
        decision = llm.generate(
            f"{chr(10).join(history)}\n\nDecide: use a tool or give final answer."
        )
        if decision.startswith("FINAL_ANSWER:"):
            return decision.replace("FINAL_ANSWER:", "").strip()

        tool_name, tool_input = parse_tool_call(decision)
        result = tools[tool_name](tool_input)
        history.append(f"Action: {tool_name}({tool_input})\nObservation: {result}")

    return "Max steps reached without a final answer."

def parse_tool_call(decision_text):
    # Simplified parser — production systems use structured function calling
    import re
    match = re.match(r"ACTION:\s*(\w+)\((.*)\)", decision_text.strip())
    return (match.group(1), match.group(2)) if match else (None, None)

import re
import json

class ReActAgent:
    """
    A from-scratch ReAct agent implementation.
    Demonstrates the mechanics that frameworks like LangChain abstract away.
    """

    def __init__(self, llm_call, tools: dict, max_iterations=6):
        self.llm_call = llm_call         # function: (prompt) -> string
        self.tools = tools                # dict: {tool_name: callable}
        self.max_iterations = max_iterations

    def build_system_prompt(self):
        tool_descriptions = "\n".join(
            f"- {name}: {func.__doc__.strip() if func.__doc__ else 'No description'}"
            for name, func in self.tools.items()
        )
        return f"""You are an AI agent that solves tasks step by step using tools.

Available tools:
{tool_descriptions}

Use EXACTLY this format for every step:
Thought: <your reasoning about what to do next>
Action: <tool_name>
Action Input: <input to the tool>

After you receive an Observation, continue with more Thought/Action/Action Input
steps as needed. When you have enough information, respond with:
Thought: <final reasoning>
Final Answer: <your complete answer to the user>

Never skip the Thought step. Never call a tool that is not in the list above."""

    def parse_response(self, text):
        """Extract the action and input, or detect a final answer"""
        if "Final Answer:" in text:
            answer = text.split("Final Answer:")[-1].strip()
            return {"type": "final_answer", "content": answer}

        action_match = re.search(r"Action:\s*(\w+)", text)
        input_match = re.search(r"Action Input:\s*(.+?)(?:\n|$)", text)

        if action_match and input_match:
            return {
                "type": "action",
                "tool": action_match.group(1).strip(),
                "input": input_match.group(1).strip()
            }
        return {"type": "unknown", "content": text}

    def run(self, question, verbose=True):
        system_prompt = self.build_system_prompt()
        transcript = [f"Question: {question}"]

        for step in range(self.max_iterations):
            full_prompt = f"{system_prompt}\n\n{chr(10).join(transcript)}\nThought:"
            response = self.llm_call(full_prompt)

            if verbose:
                print(f"\n--- Step {step + 1} ---")
                print(response)

            parsed = self.parse_response(response)

            if parsed["type"] == "final_answer":
                return parsed["content"]

            if parsed["type"] == "action":
                tool_name = parsed["tool"]
                tool_input = parsed["input"]

                if tool_name not in self.tools:
                    observation = f"Error: tool '{tool_name}' does not exist."
                else:
                    try:
                        observation = self.tools[tool_name](tool_input)
                    except Exception as e:
                        observation = f"Error executing tool: {e}"

                transcript.append(f"Thought:{response.split('Thought:')[-1].split('Action:')[0]}")
                transcript.append(f"Action: {tool_name}")
                transcript.append(f"Action Input: {tool_input}")
                transcript.append(f"Observation: {observation}")
            else:
                transcript.append(response)  # unparseable — feed back for self-correction

        return "Agent reached maximum iterations without producing a final answer."
 # Defining simple tools for the agent

