def calculate_percentage_change(old_value: float, new_value: float) -> dict:
    change = ((new_value - old_value) / old_value) * 100
    return {"percentage_change": round(change, 2)}

TOOL_REGISTRY = {
    "get_stock_price": get_stock_price,
    "calculate_percentage_change": calculate_percentage_change,
}

def run_agent_with_native_tools(user_question, max_turns=5):
    messages = [{"role": "user", "content": user_question}]

    for turn in range(max_turns):
        response = client.messages.create(
            model="claude-sonnet-4-6",
            max_tokens=1024,
            tools=tool_definitions,
            messages=messages
        )

        # Check if the model wants to use a tool
        tool_use_blocks = [block for block in response.content if block.type == "tool_use"]

        if not tool_use_blocks:
            # Model produced a final text answer — no more tools needed
            text_blocks = [block.text for block in response.content if block.type == "text"]
            return "\n".join(text_blocks)

        # Append the assistant's tool-use request to the conversation
        messages.append({"role": "assistant", "content": response.content})

        # Execute each requested tool call and collect results
        tool_results = []
        for tool_use in tool_use_blocks:
            tool_name = tool_use.name
            tool_input = tool_use.input

            if tool_name in TOOL_REGISTRY:
                result = TOOL_REGISTRY[tool_name](**tool_input)
            else:
                result = {"error": f"Unknown tool: {tool_name}"}

            tool_results.append({
                "type": "tool_result",
                "tool_use_id": tool_use.id,
                "content": json.dumps(result)
            })

        messages.append({"role": "user", "content": tool_results})

    return "Reached max turns without a final answer."

