class ShortTermMemory:
    """Simple in-context memory for the current task episode"""

    def __init__(self, max_tokens_estimate=4000):
        self.transcript = []
        self.max_tokens_estimate = max_tokens_estimate

    def add(self, entry: str):
        self.transcript.append(entry)
        self._trim_if_needed()

    def _trim_if_needed(self):
        # Simplified token estimate: ~4 chars per token
        total_chars = sum(len(e) for e in self.transcript)
        while total_chars / 4 > self.max_tokens_estimate and len(self.transcript) > 1:
            # Drop oldest entries first, but consider summarizing instead of dropping
            removed = self.transcript.pop(0)
            total_chars -= len(removed)

    def get_context(self):
        return "\n".join(self.transcript)

class LongTermMemory:
    """
    Persistent memory using vector similarity search.
    In production, backed by a real vector DB (Chroma, Pinecone, Qdrant, etc.)
    """

    def __init__(self, embedding_model, vector_store):
        self.embedding_model = embedding_model
        self.vector_store = vector_store   # any store with add() and search()

    def store_memory(self, text: str, metadata: dict = None):
        embedding = self.embedding_model.encode(text)
        self.vector_store.add(
            embedding=embedding,
            text=text,
            metadata=metadata or {}
        )

    def retrieve_relevant(self, query: str, k=5):
        query_embedding = self.embedding_model.encode(query)
        return self.vector_store.search(query_embedding, top_k=k)


