Current task: {question}

Using the above context if relevant, proceed with the task.
"""
    return llm_call(prompt)

class EpisodicMemory:
    """
    Stores structured records of complete past task episodes,
    including outcome, for reflection and few-shot-style reuse.
    """

    def __init__(self):
        self.episodes = []

    def record_episode(self, task, actions_taken, outcome, success: bool):
        self.episodes.append({
            "task": task,
            "actions_taken": actions_taken,
            "outcome": outcome,
            "success": success,
            "timestamp": __import__("datetime").datetime.now().isoformat()
        })

    def get_similar_past_episodes(self, current_task, embedding_model, k=2):
        """Retrieve similar past episodes to inform the current attempt —
        especially useful for surfacing past FAILURES to avoid repeating them"""
        if not self.episodes:
            return []

        current_embedding = embedding_model.encode(current_task)
        scored = []
        for episode in self.episodes:
            episode_embedding = embedding_model.encode(episode["task"])
            similarity = cosine_similarity(current_embedding, episode_embedding)
            scored.append((similarity, episode))

        scored.sort(key=lambda x: x[0], reverse=True)
        return [ep for _, ep in scored[:k]]

def cosine_similarity(a, b):
    import numpy as np
    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))

