def send_email_tool(to: str, subject: str, body: str) -> dict:
    """
    Sends an email to the specified recipient.

    Args:
        to: recipient email address (must be a valid email format)
        subject: email subject line
        body: email body text

    Returns:
        dict with 'success' (bool) and 'message' (str)
    """
    # Input validation — critical since the LLM-generated input can be malformed
    email_pattern = r"^[\w\.-]+@[\w\.-]+\.\w+$"
    if not re.match(email_pattern, to):
        return {"success": False, "message": f"Invalid email address: {to}"}

    if not subject or not body:
        return {"success": False, "message": "Subject and body cannot be empty"}

    # In production: actually call an email API (SendGrid, SES, etc.)
    # For now, simulate success
    return {"success": True, "message": f"Email sent to {to} with subject '{subject}'"}


def query_database_tool(sql_query: str, allowed_tables: list) -> dict:
    """
    Executes a read-only SQL query against the application database.

    Args:
        sql_query: a SELECT SQL query (writes are blocked for safety)
        allowed_tables: whitelist of tables this tool may query

    Returns:
        dict with 'success', 'rows', or 'error'
    """
    # Defense-in-depth: block anything that isn't a pure read
    forbidden_keywords = ["insert", "update", "delete", "drop", "alter", "truncate"]
    query_lower = sql_query.lower()

    if not query_lower.strip().startswith("select"):
        return {"success": False, "error": "Only SELECT queries are permitted"}

    if any(keyword in query_lower for keyword in forbidden_keywords):
        return {"success": False, "error": "Query contains forbidden operation"}

    # Table whitelist check — prevent querying tables outside this tool's scope
    referenced_tables = re.findall(r"from\s+(\w+)", query_lower)
    for table in referenced_tables:
        if table not in [t.lower() for t in allowed_tables]:
            return {"success": False, "error": f"Access to table '{table}' is not allowed"}

    # In production: execute against a real read-replica connection
    return {"success": True, "rows": []}   # placeholder result

def build_web_search_agent(search_api_call, llm_call):
    """
    A minimal web-search-augmented agent: decides whether to search,
    performs the search, and synthesizes an answer with citations.
    """

    def search_tool(query: str) -> str:
        """Searches the web and returns top results with source URLs"""
        results = search_api_call(query)  # e.g., wraps a real search API
        formatted = "\n".join(
            f"[{i+1}] {r['title']} — {r['snippet']} (Source: {r['url']})"
            for i, r in enumerate(results[:5])
        )
        return formatted

    def run(question):
        decision_prompt = f"""
Question: {question}

Does answering this question require current/factual information you should
search for, or can you answer confidently from general knowledge?
Respond with either:
NEED_SEARCH: <search query to use>
or
NO_SEARCH_NEEDED
"""
        decision = llm_call(decision_prompt)

        if decision.strip().startswith("NEED_SEARCH"):
            query = decision.split("NEED_SEARCH:")[-1].strip()
            search_results = search_tool(query)

            answer_prompt = f"""
Question: {question}

Search results:
{search_results}

Answer the question using these search results. Cite sources using [1], [2], etc.
If the search results don't fully answer the question, say what's uncertain.
"""
            return llm_call(answer_prompt)
        else:
            return llm_call(question)

    return run

import os
from pathlib import Path

class SandboxedFileSystemTool:
    """
    A file system tool restricted to a single sandboxed root directory,
    preventing path traversal outside the intended workspace.
    """

    def __init__(self, sandbox_root: str):
        self.sandbox_root = Path(sandbox_root).resolve()
        self.sandbox_root.mkdir(parents=True, exist_ok=True)

    def _resolve_safe_path(self, relative_path: str) -> Path:
        """Resolves a path and ensures it stays within the sandbox root"""
        target = (self.sandbox_root / relative_path).resolve()
        if not str(target).startswith(str(self.sandbox_root)):
            raise ValueError(f"Path traversal attempt blocked: {relative_path}")
        return target

    def read_file(self, relative_path: str) -> dict:
        """Reads the contents of a file within the sandbox"""
        try:
            path = self._resolve_safe_path(relative_path)
            if not path.exists():
                return {"success": False, "error": "File not found"}
            return {"success": True, "content": path.read_text()}
        except ValueError as e:
            return {"success": False, "error": str(e)}

    def write_file(self, relative_path: str, content: str) -> dict:
        """Writes content to a file within the sandbox"""
        try:
            path = self._resolve_safe_path(relative_path)
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content)
            return {"success": True, "message": f"Wrote {len(content)} chars to {relative_path}"}
        except ValueError as e:
            return {"success": False, "error": str(e)}

    def list_files(self, relative_path: str = ".") -> dict:
        """Lists files in a directory within the sandbox"""
        try:
            path = self._resolve_safe_path(relative_path)
            if not path.is_dir():
                return {"success": False, "error": "Not a directory"}
            entries = [str(p.relative_to(self.sandbox_root)) for p in path.iterdir()]
            return {"success": True, "entries": entries}
        except ValueError as e:
            return {"success": False, "error": str(e)}


