class OrchestratorPipeline:
    """
    Sequential orchestrator pattern: a fixed pipeline of specialized
    agents, each consuming the previous agent's output.
    """

    def __init__(self, researcher_agent, writer_agent, reviewer_agent):
        self.researcher = researcher_agent
        self.writer = writer_agent
        self.reviewer = reviewer_agent

    def run(self, topic: str) -> dict:
        research_findings = self.researcher.run(f"Research key facts about: {topic}")

        draft = self.writer.run(
            f"Write a short article about '{topic}' using these findings:\n{research_findings}"
        )

        review_feedback = self.reviewer.run(
            f"Review this draft for accuracy and clarity:\n{draft}"
        )

        # Orchestrator decides whether to loop back for revision or finish
        if "needs revision" in review_feedback.lower():
            final_draft = self.writer.run(
                f"Revise this draft based on feedback:\nDraft: {draft}\nFeedback: {review_feedback}"
            )
        else:
            final_draft = draft

        return {
            "topic": topic,
            "research": research_findings,
            "draft": draft,
            "review": review_feedback,
            "final": final_draft
        }

class SupervisorAgent:
    """
    Supervisor pattern: an LLM-driven controller that dynamically
    decides which specialized worker agent to call next, and when
    the overall task is complete.
    """

    def __init__(self, llm_call, workers: dict, max_turns=8):
        self.llm_call = llm_call
        self.workers = workers   # {"researcher": agent, "coder": agent, "critic": agent}
        self.max_turns = max_turns

    def decide_next_worker(self, task, history):
        worker_list = ", ".join(self.workers.keys())
        prompt = f"""
You are a supervisor coordinating a team of specialized agents: {worker_list}.

Task: {task}
Progress so far:
{history}

Decide which worker should act next, or if the task is complete.
Respond with exactly one of:
CALL: <worker_name>: <specific instruction for that worker>
DONE: <final synthesized answer>
"""
        return self.llm_call(prompt)

    def run(self, task):
        history = []

        for turn in range(self.max_turns):
            decision = self.decide_next_worker(task, "\n".join(history))

            if decision.strip().startswith("DONE:"):
                return decision.split("DONE:")[-1].strip()

            if decision.strip().startswith("CALL:"):
                _, rest = decision.split("CALL:", 1)
                worker_name, instruction = rest.split(":", 1)
                worker_name = worker_name.strip()
                instruction = instruction.strip()

                if worker_name not in self.workers:
                    history.append(f"Error: unknown worker '{worker_name}'")
                    continue

                result = self.workers[worker_name].run(instruction)
                history.append(f"[{worker_name}] Instruction: {instruction}\nResult: {result}")

        return "Supervisor reached max turns without completing the task."

class PeerToPeerDebate:
    """
    Peer-to-peer pattern: two or more agents converse directly,
    refining an answer through back-and-forth exchange (e.g., a
    proposer and a critic iterating until convergence).
    """

    def __init__(self, proposer_agent, critic_agent, max_rounds=4):
        self.proposer = proposer_agent
        self.critic = critic_agent
        self.max_rounds = max_rounds

    def run(self, task):
        proposal = self.proposer.run(f"Propose a solution to: {task}")
        conversation = [f"Proposer: {proposal}"]

        for round_num in range(self.max_rounds):
            critique = self.critic.run(
                f"Task: {task}\n\nCurrent proposal:\n{proposal}\n\n"
                f"Critique this proposal. If it's satisfactory, respond with "
                f"'APPROVED' followed by why. Otherwise, explain what's wrong."
            )
            conversation.append(f"Critic: {critique}")

            if critique.strip().upper().startswith("APPROVED"):
                return {"final_solution": proposal, "conversation": conversation, "rounds": round_num + 1}

            proposal = self.proposer.run(
                f"Task: {task}\n\nYour previous proposal:\n{proposal}\n\n"
                f"Critic's feedback:\n{critique}\n\nRevise your proposal."
            )
            conversation.append(f"Proposer: {proposal}")

        return {"final_solution": proposal, "conversation": conversation, "rounds": self.max_rounds}

