# A hybrid orchestrator + peer-to-peer multi-agent system:
# fixed pipeline for research/writing, with a debate loop for review

from dataclasses import dataclass, field
from typing import Callable

@dataclass
class AgentSpec:
    name: str
    system_prompt: str
    llm_call: Callable   # (system_prompt, user_message) -> response


class SpecializedAgent:
    def __init__(self, spec: AgentSpec):
        self.spec = spec

    def run(self, message: str) -> str:
        return self.spec.llm_call(self.spec.system_prompt, message)


class ContentCreationSystem:
    """
    Orchestrates: Researcher -> Writer -> [Reviewer <-> Writer debate loop] -> Final Output
    Demonstrates combining the orchestrator pattern (fixed early stages)
    with the peer-to-peer pattern (review/revision loop).
    """

    def __init__(self, researcher: SpecializedAgent, writer: SpecializedAgent,
                 reviewer: SpecializedAgent, max_review_rounds=3):
        self.researcher = researcher
        self.writer = writer
        self.reviewer = reviewer
        self.max_review_rounds = max_review_rounds

    def run(self, topic: str, verbose=True) -> dict:
        trace = []

        # --- Orchestrator stage: fixed sequence ---
        if verbose:
            print(f"[Researcher] Researching: {topic}")
        findings = self.researcher.run(f"Research key, verifiable facts about: {topic}")
        trace.append({"stage": "research", "output": findings})

        if verbose:
            print("[Writer] Drafting initial article...")
        draft = self.writer.run(
            f"Write a 300-word article about '{topic}' using these findings:\n{findings}"
        )
        trace.append({"stage": "initial_draft", "output": draft})

        # --- Peer-to-peer stage: review/revision debate loop ---
        for round_num in range(1, self.max_review_rounds + 1):
            if verbose:
                print(f"[Reviewer] Review round {round_num}...")

            review = self.reviewer.run(
                f"Original research: {findings}\n\nDraft article:\n{draft}\n\n"
                f"Check the draft against the research for factual accuracy and clarity. "
                f"If it's good, respond starting with 'APPROVED'. Otherwise, list specific issues."
            )
            trace.append({"stage": f"review_round_{round_num}", "output": review})

            if review.strip().upper().startswith("APPROVED"):
                if verbose:
                    print(f"[Reviewer] Approved after {round_num} round(s).")
                break

            if verbose:
                print(f"[Writer] Revising based on feedback...")
            draft = self.writer.run(
                f"Original draft:\n{draft}\n\nReviewer feedback:\n{review}\n\n"
                f"Revise the article to address this feedback."
            )
            trace.append({"stage": f"revision_round_{round_num}", "output": draft})
        else:
            if verbose:
                print(f"[System] Max review rounds ({self.max_review_rounds}) reached without approval.")

        return {
            "topic": topic,
            "research_findings": findings,
            "final_article": draft,
            "review_rounds_used": round_num,
            "full_trace": trace
        }


