def recommend_approach(requirements: dict) -> str:
    """
    A simplified decision heuristic — real decisions usually combine
    multiple approaches (e.g., RAG + fine-tuning for style).
    """
    if requirements.get("needs_current_facts") or requirements.get("has_proprietary_docs"):
        if requirements.get("needs_consistent_output_format_at_scale"):
            return "RAG + Fine-tuning (retrieval for facts, fine-tuning for format/style)"
        return "RAG"

    if requirements.get("task_is_novel_or_unusual_format"):
        if requirements.get("prompt_engineering_already_tried_and_insufficient"):
            return "Fine-tuning (SFT or instruction tuning)"
        return "Try prompt engineering first (cheaper, faster iteration)"

    if requirements.get("needs_smaller_cheaper_model_matching_larger_model_quality"):
        return "Fine-tuning (distillation-style SFT on a smaller base model)"

    if requirements.get("output_needs_stylistic_consistency_across_thousands_of_calls"):
        return "Fine-tuning (reduces per-call prompt engineering overhead and token cost)"

    return "Prompt engineering (cheapest, fastest to iterate, no training infrastructure needed)"

