def evaluate_mmlu_style(model, questions):
    """Simplified MMLU-style evaluation — multiple choice, exact match"""
    correct = 0
    for q in questions:
        prompt = f"{q['question']}\n" + "\n".join(q['choices']) + "\nAnswer with only the letter:"
        prediction = model.generate(prompt).strip().upper()[:1]
        if prediction == q["answer"]:
            correct += 1
    return correct / len(questions)

