def extract_final_number(text):
    import re
    numbers = re.findall(r"-?\d+\.?\d*", text)
    return numbers[-1] if numbers else None

def llm_as_judge_score(question, response, llm_judge_call, rubric=None):
    """
    A basic LLM-as-judge implementation scoring a single response
    against a rubric on a numeric scale.
    """
    default_rubric = """
Rate the response on a scale of 1-5 for each of these dimensions:
- Accuracy: Is the information correct?
- Completeness: Does it fully address the question?
- Clarity: Is it well-organized and easy to understand?

Respond in this exact JSON format:
{"accuracy": <1-5>, "completeness": <1-5>, "clarity": <1-5>, "reasoning": "<brief explanation>"}
"""
    prompt = f"""
Question: {question}
Response to evaluate: {response}

{rubric or default_rubric}
"""
    judge_output = llm_judge_call(prompt)
    return parse_judge_output(judge_output)

def parse_judge_output(text):
    import json
    cleaned = text.strip().strip("```json").strip("```").strip()
    return json.loads(cleaned)

def pairwise_judge(question, response_a, response_b, llm_judge_call):
    """
    Pairwise comparison — the basis of most production LLM-as-judge
    systems (and of preference data collection for DPO, Chapter 82).
    """
    prompt = f"""
Question: {question}

Response A: {response_a}
Response B: {response_b}

Which response better answers the question? Consider accuracy, completeness,
and clarity. Respond with exactly one of: "A", "B", or "TIE", followed by
a one-sentence justification.
"""
    result = llm_judge_call(prompt)
    verdict = result.strip().split()[0].upper()
    return {"verdict": verdict, "full_response": result}

