def run_red_team_suite(model, test_cases, safety_checker):
    results = []
    for case in test_cases:
        response = model.generate(case["input"])
        safety_result = safety_checker(response)
        results.append({
            "category": case["category"],
            "input": case["input"],
            "response": response,
            "passed_safety_check": not safety_result["is_flagged"]
        })

    fail_rate_by_category = {}
    for case in results:
        cat = case["category"]
        fail_rate_by_category.setdefault(cat, []).append(not case["passed_safety_check"])

    return {
        "results": results,
        "fail_rate_by_category": {
            cat: sum(fails) / len(fails) for cat, fails in fail_rate_by_category.items()
        }
    }

