# A unified evaluation harness combining benchmark-style accuracy,
# RAG-specific metrics, LLM-as-judge scoring, and safety checks —
# producing a single structured report, the kind of tool a GenAI
# team builds early to track quality across changes over time

from dataclasses import dataclass, field
from datetime import datetime
import json

@dataclass
class EvaluationResult:
    test_name: str
    category: str    # "accuracy", "rag_quality", "judge_score", "safety"
    score: float
    details: dict = field(default_factory=dict)
    timestamp: str = field(default_factory=lambda: datetime.now().isoformat())


class LLMEvaluationDashboard:
    """
    Aggregates multiple evaluation methods into one report, and tracks
    results over time to detect regressions across model/prompt changes.
    """

    def __init__(self):
        self.results: list[EvaluationResult] = []
        self.history: list[dict] = []   # snapshot per evaluation run

    def run_accuracy_eval(self, name, model_generate_fn, test_questions):
        correct = 0
        for q in test_questions:
            prediction = model_generate_fn(q["question"]).strip()
            if q["expected_answer"].lower() in prediction.lower():
                correct += 1
        score = correct / len(test_questions)
        self.results.append(EvaluationResult(
            test_name=name, category="accuracy", score=score,
            details={"total": len(test_questions), "correct": correct}
        ))
        return score

    def run_faithfulness_eval(self, name, response_context_pairs, llm_judge_call):
        scores = []
        unsupported_details = []
        for pair in response_context_pairs:
            result = check_faithfulness(pair["response"], pair["context"], llm_judge_call)
            scores.append(result["faithfulness_score"])
            if result["unsupported_claims"]:
                unsupported_details.append(result["unsupported_claims"])

        avg_score = sum(scores) / len(scores)
        self.results.append(EvaluationResult(
            test_name=name, category="rag_quality", score=avg_score,
            details={"per_example_scores": scores, "unsupported_claims_found": unsupported_details}
        ))
        return avg_score

    def run_judge_comparison(self, name, question_response_pairs, llm_judge_call):
        scores = []
        for pair in question_response_pairs:
            result = llm_as_judge_score(pair["question"], pair["response"], llm_judge_call)
            avg = (result["accuracy"] + result["completeness"] + result["clarity"]) / 3
            scores.append(avg)

        overall = sum(scores) / len(scores) / 5.0  # normalize to 0-1
        self.results.append(EvaluationResult(
            test_name=name, category="judge_score", score=overall,
            details={"raw_scores": scores}
        ))
        return overall

    def run_safety_eval(self, name, test_cases, model_generate_fn, safety_checker):
        result = run_red_team_suite(
            model={"generate": model_generate_fn}, test_cases=test_cases,
            safety_checker=safety_checker
        )
        pass_rate = 1 - (sum(result["fail_rate_by_category"].values()) /
                          len(result["fail_rate_by_category"]))
        self.results.append(EvaluationResult(
            test_name=name, category="safety", score=pass_rate,
            details=result["fail_rate_by_category"]
        ))
        return pass_rate

    def generate_report(self) -> str:
        report_lines = [
            "=" * 65,
            "  LLM EVALUATION DASHBOARD REPORT",
            f"  Generated: {datetime.now().isoformat()}",
            "=" * 65
        ]

        by_category = {}
        for r in self.results:
            by_category.setdefault(r.category, []).append(r)

        for category, results in by_category.items():
            report_lines.append(f"\n--- {category.upper()} ---")
            for r in results:
                status = "✓" if r.score >= 0.8 else ("⚠" if r.score >= 0.6 else "✗")
                report_lines.append(f"  [{status}] {r.test_name}: {r.score:.3f}")

        overall_avg = sum(r.score for r in self.results) / len(self.results) if self.results else 0
        report_lines.append(f"\n{'='*65}")
        report_lines.append(f"  OVERALL AVERAGE SCORE: {overall_avg:.3f}")
        report_lines.append("=" * 65)

        return "\n".join(report_lines)

    def save_snapshot(self, filepath):
        snapshot = {
            "timestamp": datetime.now().isoformat(),
            "results": [
                {"test_name": r.test_name, "category": r.category,
                 "score": r.score, "details": r.details}
                for r in self.results
            ]
        }
        self.history.append(snapshot)
        with open(filepath, "w") as f:
            json.dump(self.history, f, indent=2)

    def detect_regression(self, previous_snapshot: dict, threshold=0.05):
        """Compares current results against a saved previous snapshot"""
        prev_scores = {r["test_name"]: r["score"] for r in previous_snapshot["results"]}
        regressions = []

        for r in self.results:
            if r.test_name in prev_scores:
                delta = r.score - prev_scores[r.test_name]
                if delta < -threshold:
                    regressions.append({
                        "test_name": r.test_name,
                        "previous_score": prev_scores[r.test_name],
                        "current_score": r.score,
                        "delta": delta
                    })
        return regressions


