@tool
def analyze_python_syntax(code: str) -> str:
    """
    Analyzes Python code for syntax errors using the AST module.
    Returns syntax validity and any parse errors found.
    """
    try:
        tree = ast.parse(code)
        n_functions = sum(1 for _ in ast.walk(tree)
                         if isinstance(_, ast.FunctionDef))
        n_classes   = sum(1 for _ in ast.walk(tree)
                         if isinstance(_, ast.ClassDef))
        n_imports   = sum(1 for _ in ast.walk(tree)
                         if isinstance(_, (ast.Import, ast.ImportFrom)))

        return json.dumps({
            "syntax_valid":  True,
            "n_functions":   n_functions,
            "n_classes":     n_classes,
            "n_imports":     n_imports,
            "message":       "Code parsed successfully"
        })
    except SyntaxError as e:
        return json.dumps({
            "syntax_valid": False,
            "error":        str(e),
            "line":         e.lineno,
            "message":      f"Syntax error at line {e.lineno}: {e.msg}"
        })


@tool
def check_security_patterns(code: str) -> str:
    """
    Scans code for common security vulnerabilities and anti-patterns.
    Checks for SQL injection, hardcoded credentials, unsafe functions, etc.
    """
    security_patterns = {
        "sql_injection":        r"execute\(['\"].*\+|f['\"].*SELECT|f['\"].*INSERT",
        "hardcoded_password":   r"password\s*=\s*['\"][^'\"]{4,}['\"]",
        "hardcoded_token":      r"(api_key|token|secret)\s*=\s*['\"][^'\"]{10,}['\"]",
        "shell_injection":      r"os\.system\(|subprocess\.call\([^)]*shell=True",
        "pickle_unsafe":        r"pickle\.loads\(",
        "eval_usage":           r"\beval\s*\(",
        "exec_usage":           r"\bexec\s*\(",
        "debug_breakpoint":     r"import pdb|breakpoint\(\)|pdb\.set_trace",
        "print_debug":          r"print\(['\"]DEBUG|print\(['\"]TEMP",
        "unsafe_yaml":          r"yaml\.load\([^,)]*\)(?!\s*,\s*Loader)",
        "no_ssl_verify":        r"verify\s*=\s*False",
    }

    findings = []
    lines    = code.split('\n')

    for pattern_name, pattern in security_patterns.items():
        for line_num, line in enumerate(lines, 1):
            if re.search(pattern, line, re.IGNORECASE):
                findings.append({
                    "pattern":      pattern_name,
                    "line":         line_num,
                    "code_snippet": line.strip()[:100],
                })

    result = {
        "n_issues":    len(findings),
        "findings":    findings,
        "message":     (f"Found {len(findings)} security concerns"
                       if findings else "No obvious security issues detected")
    }
    return json.dumps(result)


@tool
def check_code_complexity(code: str) -> str:
    """
    Analyzes code complexity metrics: function length, nesting depth,
    parameter count, and identifies potential complexity hotspots.
    """
    lines   = code.split('\n')
    metrics = {
        "total_lines":      len(lines),
        "code_lines":       len([l for l in lines if l.strip() and
                                 not l.strip().startswith('#')]),
        "comment_lines":    len([l for l in lines if l.strip().startswith('#')]),
        "blank_lines":      len([l for l in lines if not l.strip()]),
        "long_functions":   [],
        "deep_nesting":     [],
        "many_params":      [],
    }

    # Find functions and their lengths
    try:
        tree = ast.parse(code)
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                func_lines = (node.end_lineno or node.lineno) - node.lineno
                n_params   = len(node.args.args)

                if func_lines > 50:
                    metrics["long_functions"].append({
                        "name":  node.name,
                        "lines": func_lines,
                        "line":  node.lineno
                    })
                if n_params > 5:
                    metrics["many_params"].append({
                        "name":   node.name,
                        "params": n_params,
                        "line":   node.lineno
                    })
    except SyntaxError:
        metrics["parse_error"] = True

    # Check nesting depth
    max_indent = 0
    for line in lines:
        if line.strip():
            indent = len(line) - len(line.lstrip())
            depth  = indent // 4
            if depth > max_indent:
                max_indent = depth

    metrics["max_nesting_depth"] = max_indent
    if max_indent > 4:
        metrics["deep_nesting"] = [{"depth": max_indent}]

    metrics["message"] = (
        f"Code has {metrics['total_lines']} lines, "
        f"max nesting depth {max_indent}, "
        f"{len(metrics['long_functions'])} long functions"
    )
    return json.dumps(metrics)


@tool
def check_docstrings_and_types(code: str) -> str:
    """
    Checks for documentation quality: missing docstrings,
    type annotations, and README-level documentation.
    """
    issues   = []
    coverage = {"total_functions": 0, "with_docstring": 0, "with_types": 0}

    try:
        tree = ast.parse(code)
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                coverage["total_functions"] += 1

                # Check for docstring
                has_docstring = (
                    node.body and
                    isinstance(node.body[0], ast.Expr) and
                    isinstance(node.body[0].value, ast.Constant)
                )
                if has_docstring:
                    coverage["with_docstring"] += 1
                else:
                    issues.append({
                        "type": "missing_docstring",
                        "function": node.name,
                        "line": node.lineno
                    })

                # Check for type annotations
                has_return_type = node.returns is not None
                all_params_typed = all(
                    arg.annotation is not None
                    for arg in node.args.args
                    if arg.arg != 'self'
                )
                if has_return_type and all_params_typed:
                    coverage["with_types"] += 1
                elif node.name != "__init__":
                    issues.append({
                        "type": "missing_types",
                        "function": node.name,
                        "line": node.lineno,
                        "has_return": has_return_type,
                        "all_params": all_params_typed
                    })

    except SyntaxError:
        pass

    if coverage["total_functions"] > 0:
        coverage["docstring_pct"] = round(
            coverage["with_docstring"] / coverage["total_functions"] * 100, 1
        )
        coverage["type_pct"] = round(
            coverage["with_types"] / coverage["total_functions"] * 100, 1
        )

    return json.dumps({
        "issues": issues[:10],
        "coverage": coverage,
        "message": (
            f"{coverage.get('docstring_pct', 0)}% docstring coverage, "
            f"{coverage.get('type_pct', 0)}% type annotation coverage"
        )
    })


