app = FastAPI(
    title="Sentiment Analysis Service",
    description="Production sentiment classification API with authentication and logging",
    version="1.0.0",
    lifespan=lifespan
)

class SentimentRequest(BaseModel):
    text: str = Field(..., min_length=1, max_length=2000)

class SentimentResponse(BaseModel):
    text: str
    label: str
    confidence: float

class BatchSentimentRequest(BaseModel):
    texts: List[str] = Field(..., min_length=1, max_length=100)

def verify_api_key(api_key: str = Security(API_KEY_HEADER)):
    if api_key not in VALID_API_KEYS:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid or missing API key"
        )
    return api_key

def log_request(text: str, label: str, confidence: float):
    """Background logging — does not delay the API response"""
    timestamp = datetime.datetime.now().isoformat()
    logger.info(f"[{timestamp}] Prediction logged | label={label} | confidence={confidence:.4f}")

@app.post("/predict", response_model=SentimentResponse, tags=["Predictions"])
def predict_sentiment(
    request: SentimentRequest,
    background_tasks: BackgroundTasks,
    api_key: str = Security(verify_api_key)
):
    """Classifies the sentiment of a single piece of text as POSITIVE or NEGATIVE."""
    try:
        result = ml_models["sentiment"](request.text)[0]
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Inference failed: {str(e)}")

    background_tasks.add_task(log_request, request.text, result["label"], result["score"])

    return SentimentResponse(
        text=request.text,
        label=result["label"],
        confidence=round(result["score"], 4)
    )

@app.post("/predict-batch", response_model=List[SentimentResponse], tags=["Predictions"])
def predict_sentiment_batch(
    request: BatchSentimentRequest,
    api_key: str = Security(verify_api_key)
):
    """Classifies sentiment for up to 100 texts in a single efficient batched call."""
    try:
        results = ml_models["sentiment"](request.texts, truncation=True, batch_size=16)
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Batch inference failed: {str(e)}")

    return [
        SentimentResponse(text=text, label=r["label"], confidence=round(r["score"], 4))
        for text, r in zip(request.texts, results)
    ]

@app.get("/health", tags=["Monitoring"])
def health_check():
    return {
        "status": "healthy",
        "model_loaded": "sentiment" in ml_models
    }

