import requests

def send_slack_alert(message: str, webhook_url: str):
    requests.post(webhook_url, json={"text": message})

def evaluate_and_alert(drift_result: dict, performance_result: dict, config: dict):
    alerts = []

    if drift_result.get("drift_detected"):
        alerts.append({
            "severity": "warning",
            "message": f"Data drift detected: PSI={drift_result.get('psi_score', 'N/A')}"
        })

    if performance_result.get("accuracy", 1.0) < config["min_acceptable_accuracy"]:
        alerts.append({
            "severity": "critical",
            "message": f"Model accuracy dropped to {performance_result['accuracy']:.3f}, "
                      f"below minimum {config['min_acceptable_accuracy']}"
        })

    for alert in alerts:
        formatted = f"[{alert['severity'].upper()}] {alert['message']}"
        print(formatted)

        if alert["severity"] == "critical":
            send_slack_alert(formatted, config["slack_webhook_url"])
            # Critical alerts might also page an on-call engineer via PagerDuty/Opsgenie

    return alerts

# monitoring_dashboard.py
# Combines drift detection, proxy performance signals, and alerting
# into a single scheduled monitoring script — a realistic MLOps deliverable

import pandas as pd
import numpy as np
from scipy import stats
import json
from datetime import datetime

class ModelMonitor:
    def __init__(self, reference_data: pd.DataFrame, config: dict):
        self.reference_data = reference_data
        self.config = config
        self.results_log = []

    def check_numerical_drift(self, current_data: pd.DataFrame, columns: list):
        drift_results = {}
        for col in columns:
            statistic, p_value = stats.ks_2samp(
                self.reference_data[col].dropna(),
                current_data[col].dropna()
            )
            drift_results[col] = {
                "ks_statistic": round(statistic, 4),
                "p_value": round(p_value, 6),
                "drift_detected": p_value < self.config["drift_alpha"]
            }
        return drift_results

    def check_prediction_distribution_shift(self, current_predictions: pd.Series):
        reference_dist = self.reference_data["prediction"].value_counts(normalize=True)
        current_dist = current_predictions.value_counts(normalize=True)

        shifts = {}
        for label in reference_dist.index:
            ref_pct = reference_dist.get(label, 0)
            cur_pct = current_dist.get(label, 0)
            relative_change = abs(cur_pct - ref_pct) / ref_pct if ref_pct > 0 else 0
            shifts[label] = {
                "reference_pct": round(ref_pct, 4),
                "current_pct": round(cur_pct, 4),
                "relative_change": round(relative_change, 4),
                "significant_shift": relative_change > self.config["prediction_shift_threshold"]
            }
        return shifts

    def generate_report(self, current_data: pd.DataFrame, numerical_columns: list):
        timestamp = datetime.now().isoformat()

        drift_results = self.check_numerical_drift(current_data, numerical_columns)
        prediction_shifts = self.check_prediction_distribution_shift(current_data["prediction"])

        n_drifted = sum(1 for r in drift_results.values() if r["drift_detected"])
        n_shifted = sum(1 for s in prediction_shifts.values() if s["significant_shift"])

        overall_status = "ALERT" if (n_drifted > 0 or n_shifted > 0) else "HEALTHY"

        report = {
            "timestamp": timestamp,
            "overall_status": overall_status,
            "drifted_features": [col for col, r in drift_results.items() if r["drift_detected"]],
            "feature_drift_details": drift_results,
            "prediction_distribution_shifts": prediction_shifts,
        }

        self.results_log.append(report)
        return report

    def print_report(self, report: dict):
        print("=" * 70)
        print(f"  MODEL MONITORING REPORT — {report['timestamp']}")
        print("=" * 70)
        print(f"Overall Status: {report['overall_status']}")

        if report["drifted_features"]:
            print(f"\n⚠️  Drifted Features: {', '.join(report['drifted_features'])}")
            for feature in report["drifted_features"]:
                details = report["feature_drift_details"][feature]
                print(f"   {feature}: KS={details['ks_statistic']}, p={details['p_value']}")
        else:
            print("\n✓ No numerical feature drift detected")

        significant_shifts = {k: v for k, v in report["prediction_distribution_shifts"].items()
                              if v["significant_shift"]}
