import hashlib
import json

class ExactMatchCache:
    def __init__(self):
        self._cache = {}

    def _key(self, prompt, model, temperature):
        raw = json.dumps({"prompt": prompt, "model": model, "temperature": temperature}, sort_keys=True)
        return hashlib.sha256(raw.encode()).hexdigest()

    def get(self, prompt, model, temperature):
        return self._cache.get(self._key(prompt, model, temperature))

    def set(self, prompt, model, temperature, response):
        self._cache[self._key(prompt, model, temperature)] = response

# Approximate per-model pricing (illustrative — always check current provider pricing)
MODEL_PRICING = {
    "gpt-4o": {"input": 2.50, "output": 10.00},        # per 1M tokens
    "gpt-4o-mini": {"input": 0.15, "output": 0.60},
    "claude-sonnet": {"input": 3.00, "output": 15.00},
}

def calculate_cost(model, input_tokens, output_tokens):
    pricing = MODEL_PRICING[model]
    input_cost = (input_tokens / 1_000_000) * pricing["input"]
    output_cost = (output_tokens / 1_000_000) * pricing["output"]
    return round(input_cost + output_cost, 6)


def call_and_track_cost(client, model, messages, cost_log):
    response = client.chat.completions.create(model=model, messages=messages)

    usage = response.usage
    cost = calculate_cost(model, usage.prompt_tokens, usage.completion_tokens)

    cost_log.append({
        "model": model,
        "input_tokens": usage.prompt_tokens,
        "output_tokens": usage.completion_tokens,
        "cost_usd": cost,
    })

    return response, cost

def check_output_guardrails(response_text, expected_format=None):
    """
    Checks applied AFTER receiving the LLM's response, before returning to the user.
    """
    issues = []

    # Format validation — critical when the application expects structured output
    if expected_format == "json":
        try:
            json.loads(response_text)
        except json.JSONDecodeError:
            issues.append("invalid_json_format")

    # Basic topic/relevance check — flag suspiciously off-topic or empty responses
    if len(response_text.strip()) == 0:
        issues.append("empty_response")

    # Simple toxicity/safety keyword check (production systems use dedicated
    # classifiers or moderation APIs rather than keyword matching)
    unsafe_patterns = ["how to make a weapon", "illegal drug synthesis"]
    if any(pattern in response_text.lower() for pattern in unsafe_patterns):
        issues.append("unsafe_content_detected")

    return issues


def generate_with_guardrails(client, model, messages, expected_format=None):
    user_message = messages[-1]["content"]

    input_issues = check_input_guardrails(user_message)
    if input_issues:
        return {"error": "input_rejected", "issues": input_issues}

    response = client.chat.completions.create(model=model, messages=messages)
    response_text = response.choices[0].message.content

    output_issues = check_output_guardrails(response_text, expected_format)
    if output_issues:
        return {"error": "output_rejected", "issues": output_issues, "raw_response": response_text}

    return {"response": response_text, "issues": []}

