# hybrid_search_engine.py
# Combines BM25 lexical search and semantic embedding search via
# Reciprocal Rank Fusion — the complete hybrid pattern from this chapter

import math
import numpy as np
from collections import Counter

class BM25:
    def __init__(self, tokenized_corpus, k1=1.5, b=0.75):
        self.corpus = tokenized_corpus
        self.k1, self.b = k1, b
        self.doc_lengths = [len(doc) for doc in tokenized_corpus]
        self.avgdl = sum(self.doc_lengths) / len(tokenized_corpus)
        self.doc_freqs = [Counter(doc) for doc in tokenized_corpus]
        self.n_docs = len(tokenized_corpus)
        self.idf = self._compute_idf()

    def _compute_idf(self):
        df = Counter()
        for doc in self.corpus:
            for term in set(doc):
                df[term] += 1
        return {t: math.log((self.n_docs - f + 0.5) / (f + 0.5) + 1) for t, f in df.items()}

    def score(self, query_terms, doc_idx):
        doc_freq, doc_len = self.doc_freqs[doc_idx], self.doc_lengths[doc_idx]
        score = 0.0
        for term in query_terms:
            if term not in doc_freq:
                continue
            f = doc_freq[term]
            idf = self.idf.get(term, 0)
            denom = f + self.k1 * (1 - self.b + self.b * doc_len / self.avgdl)
            score += idf * (f * (self.k1 + 1)) / denom
        return score

    def rank(self, query_terms):
        scores = [(i, self.score(query_terms, i)) for i in range(self.n_docs)]
        scores.sort(key=lambda x: x[1], reverse=True)
        return [doc_idx for doc_idx, _ in scores if _ > 0]


class MockSemanticEmbedder:
    """
    Simplified stand-in for a real sentence embedding model.
    Uses word-overlap-weighted random vectors so semantically similar
    (word-overlapping) sentences land closer together — for demonstration
    without requiring a real embedding model download.
    """
    def __init__(self, dim=32):
        self.dim = dim
        self.word_vectors = {}

    def _get_word_vector(self, word):
        if word not in self.word_vectors:
            np.random.seed(abs(hash(word)) % (2**32))
            self.word_vectors[word] = np.random.normal(0, 1, self.dim)
        return self.word_vectors[word]

    def embed(self, tokens):
        vectors = [self._get_word_vector(t) for t in tokens]
        embedding = np.mean(vectors, axis=0)
        return embedding / (np.linalg.norm(embedding) + 1e-8)


class HybridSearchEngine:
    def __init__(self, tokenized_corpus, raw_corpus):
        self.raw_corpus = raw_corpus
        self.bm25 = BM25(tokenized_corpus)
        self.embedder = MockSemanticEmbedder()
        self.doc_embeddings = np.array([self.embedder.embed(doc) for doc in tokenized_corpus])

    def semantic_rank(self, query_tokens):
        query_emb = self.embedder.embed(query_tokens)
        similarities = self.doc_embeddings @ query_emb
        ranked = np.argsort(similarities)[::-1]
        return [int(i) for i in ranked]

    def reciprocal_rank_fusion(self, ranked_lists, k=60):
        scores = {}
        for ranked_list in ranked_lists:
            for rank, doc_id in enumerate(ranked_list, start=1):
                scores[doc_id] = scores.get(doc_id, 0) + 1 / (k + rank)
        return sorted(scores.items(), key=lambda x: x[1], reverse=True)

    def search(self, query, top_k=5):
        query_tokens = query.lower().split()

        bm25_ranking = self.bm25.rank(query_tokens)
        semantic_ranking = self.semantic_rank(query_tokens)

        fused = self.reciprocal_rank_fusion([bm25_ranking, semantic_ranking])

        results = []
        for doc_id, score in fused[:top_k]:
            results.append({
                "document": " ".join(self.raw_corpus[doc_id]),
                "fused_score": round(score, 5),
                "in_bm25_top": doc_id in bm25_ranking[:top_k],
                "in_semantic_top": doc_id in semantic_ranking[:top_k],
            })
        return results


def main():
    raw_corpus = [
        "wireless bluetooth headphones with active noise cancellation".split(),
        "wired gaming headset with built in microphone".split(),
        "portable bluetooth speaker waterproof design".split(),
        "noise cancelling wireless earbuds ideal for running".split(),
        "mechanical gaming keyboard with rgb backlighting".split(),
        "over ear studio headphones for audio professionals".split(),
    ]

    engine = HybridSearchEngine(raw_corpus, raw_corpus)

    queries = [
        "wireless noise cancelling headphones",
        "gaming accessories with rgb",
    ]

    for query in queries:
        print(f"\n{'='*70}")
        print(f"  QUERY: '{query}'")
        print(f"{'='*70}")
        results = engine.search(query, top_k=4)
        for i, result in enumerate(results, 1):
            flags = []
            if result["in_bm25_top"]:
                flags.append("BM25")
            if result["in_semantic_top"]:
                flags.append("Semantic")
            print(f"{i}. [{result['fused_score']:.5f}] ({', '.join(flags) or 'fusion-only'}) "
                  f"{result['document']}")


if __name__ == "__main__":
    main()

