        print(f"\n{project}")
        print(f"  Competencies: {', '.join(info['competencies'])}")
        print(f"  Connects to: {info['system_design_link']}")
        all_competencies.update(info["competencies"])

    print(f"\n{'='*70}")
    print(f"  COMBINED COMPETENCY COVERAGE ({len(all_competencies)} distinct areas)")
    print(f"{'='*70}")
    for comp in sorted(all_competencies):
        print(f"  - {comp}")

    print("\nSuggested narrative framing for interviews:")
    print("  'My portfolio demonstrates end-to-end AI engineering: from")
    print("   agentic reasoning systems, through production MLOps automation,")
    print("   to rigorous evaluation practices across both classical ML and")
    print("   GenAI applications — not just individual model training.'")


